#ifndef KIOTTY_NET_INTERNAL_CORE_CLOCK_H
#define KIOTTY_NET_INTERNAL_CORE_CLOCK_H

#include <cstdint>

namespace kiotty::net::implementation
{
    inline constexpr uint32_t EXPIRED_MILLISECONDS = 1;

    uint64_t monotonicMilliseconds();
}

#endif

#include <chrono>

namespace kiotty::net::implementation
{
    uint64_t monotonicMilliseconds()
    {
        using Milliseconds = std::chrono::milliseconds;
        const std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now();
        const std::chrono::steady_clock::duration since_epoch = now.time_since_epoch();
        const Milliseconds elapsed = std::chrono::duration_cast<Milliseconds>(since_epoch);
        return static_cast<uint64_t>(elapsed.count());
    }
}

namespace kiotty::net::implementation
{
    Deadline::Deadline(uint32_t timeout_milliseconds)
        : _end(monotonicMilliseconds() + timeout_milliseconds)
        , _limited(timeout_milliseconds != 0)
    {
    }

    bool Deadline::limited() const
    {
        return _limited;
    }

    bool Deadline::expired() const
    {
        if (!_limited) { return false; }
        return monotonicMilliseconds() >= _end;
    }

    uint32_t Deadline::remaining() const
    {
        if (!_limited) { return 0; }
        const uint64_t now = monotonicMilliseconds();
        if (now >= _end) { return 0; }
        return static_cast<uint32_t>(_end - now);
    }

    uint32_t Deadline::bound(uint32_t timeout_milliseconds) const
    {
        if (!_limited) { return timeout_milliseconds; }
        const uint32_t left = remaining();
        const uint32_t positive = left == 0 ? 1 : left;
        if (timeout_milliseconds == 0) { return positive; }
        return timeout_milliseconds < positive ? timeout_milliseconds : positive;
    }
}

#ifndef KIOTTY_NET_INTERNAL_CORE_PARSE_INTEGER_H
#define KIOTTY_NET_INTERNAL_CORE_PARSE_INTEGER_H

#include <cstdint>

namespace kiotty::net::implementation
{
    using UnsignedResult = Result<uint64_t, KiottyNetCode>;

    UnsignedResult parseUnsigned(Span<const char> text);
    UnsignedResult parseHexadecimal(Span<const char> text);
}

#endif

#ifndef KIOTTY_NET_INTERNAL_CORE_CHECKED_H
#define KIOTTY_NET_INTERNAL_CORE_CHECKED_H

#include <limits>
#include <type_traits>

namespace kiotty::net::implementation
{
    template <typename Integer>
    Result<Integer, KiottyNetCode> checkedAdd(Integer left, Integer right)
    {
        static_assert(std::is_unsigned<Integer>::value, "checkedAdd: unsigned integers only");
        using Checked = Result<Integer, KiottyNetCode>;
        const Integer room = std::numeric_limits<Integer>::max() - right;
        if (left > room) { return Checked::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT); }
        return Checked::success(static_cast<Integer>(left + right));
    }

    template <typename Integer>
    Result<Integer, KiottyNetCode> checkedMultiply(Integer left, Integer right)
    {
        static_assert(std::is_unsigned<Integer>::value, "checkedMultiply: unsigned integers only");
        using Checked = Result<Integer, KiottyNetCode>;
        if (left == 0 || right == 0) { return Checked::success(Integer{ 0 }); }
        const Integer room = std::numeric_limits<Integer>::max() / right;
        if (left > room) { return Checked::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT); }
        return Checked::success(static_cast<Integer>(left * right));
    }
}

#endif

#include <cstddef>

namespace kiotty::net::implementation
{
    namespace
    {
        struct Radix
        {
            uint64_t base;
            size_t   max_digits;
        };

        constexpr Radix    DECIMAL{ 10, 20 };
        constexpr Radix    HEXADECIMAL{ 16, 16 };
        constexpr uint64_t NOT_A_DIGIT = 0xFF;
        constexpr uint64_t FIRST_LETTER_DIGIT = 10;

        UnsignedResult parseDigits(Span<const char> text, Radix radix);
        UnsignedResult appendDigit(uint64_t value, uint64_t digit, uint64_t base);
        uint64_t       digitOf(char character);
    }

    UnsignedResult parseUnsigned(Span<const char> text)
    {
        return parseDigits(text, DECIMAL);
    }

    UnsignedResult parseHexadecimal(Span<const char> text)
    {
        return parseDigits(text, HEXADECIMAL);
    }

    namespace
    {
        UnsignedResult parseDigits(Span<const char> text, Radix radix)
        {
            const bool is_sized = text.length > 0 && text.length <= radix.max_digits;
            if (!is_sized) { return UnsignedResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT); }
            uint64_t value = 0;
            for (size_t i = 0; i < text.length; ++i)
            {
                const UnsignedResult next = appendDigit(value, digitOf(text[i]), radix.base);
                if (!next) { return next; }
                value = next.value;
            }
            return UnsignedResult::success(value);
        }

        UnsignedResult appendDigit(uint64_t value, uint64_t digit, uint64_t base)
        {
            if (digit >= base) { return UnsignedResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT); }
            const UnsignedResult shifted = checkedMultiply<uint64_t>(value, base);
            if (!shifted) { return shifted; }
            return checkedAdd<uint64_t>(shifted.value, digit);
        }

        uint64_t digitOf(char character)
        {
            const bool is_decimal = character >= '0' && character <= '9';
            if (is_decimal) { return static_cast<uint64_t>(character - '0'); }
            const bool is_lower = character >= 'a' && character <= 'f';
            if (is_lower) { return static_cast<uint64_t>(character - 'a') + FIRST_LETTER_DIGIT; }
            const bool is_upper = character >= 'A' && character <= 'F';
            if (is_upper) { return static_cast<uint64_t>(character - 'A') + FIRST_LETTER_DIGIT; }
            return NOT_A_DIGIT;
        }
    }
}

#include <cassert>
#include <cstring>

namespace kiotty::net::implementation
{
    StageBase::Provider::Provider(StageBase& stage)
        : _stage(stage)
    {
    }

    size_t StageBase::Provider::writable() const
    {
        return _stage._capacity - _stage._end_position;
    }

    char* StageBase::Provider::prepare(size_t requested)
    {
        if (_stage._capacity == 0 || requested > writable()) { return nullptr; }
        return _stage._buffer + _stage._end_position;
    }

    void StageBase::Provider::commit(size_t written)
    {
        const size_t room = writable();
        assert(written <= room);
        const size_t accepted = written > room ? room : written;
        _stage._end_position += accepted;
    }

    StageBase::Consumer::Consumer(StageBase& stage)
        : _stage(stage)
    {
    }

    size_t StageBase::Consumer::readable() const
    {
        return _stage._end_position - _stage._begin_position;
    }

    char* StageBase::Consumer::peek()
    {
        if (_stage._capacity == 0) { return nullptr; }
        return _stage._buffer + _stage._begin_position;
    }

    void StageBase::Consumer::commit(size_t consumed)
    {
        const size_t ready = readable();
        assert(consumed <= ready);
        const size_t accepted = consumed > ready ? ready : consumed;
        _stage._begin_position += accepted;
    }

    StageBase::StageBase(Span<char> storage)
        : _buffer(storage.data)
        , _maximum(storage.length)
        , _capacity(storage.length)
        , _begin_position(0)
        , _end_position(0)
    {
    }

    void StageBase::bind(Span<char> storage)
    {
        _buffer = storage.data;
        _maximum = storage.length;
        _capacity = storage.length;
        _begin_position = 0;
        _end_position = 0;
    }

    size_t StageBase::capacity() const
    {
        return _capacity;
    }

    size_t StageBase::maximum() const
    {
        return _maximum;
    }

    StageBase::Provider StageBase::provider()
    {
        return Provider(*this);
    }

    StageBase::Consumer StageBase::consumer()
    {
        return Consumer(*this);
    }

    void StageBase::compact()
    {
        const size_t unread = _end_position - _begin_position;
        if (unread > 0 && _begin_position > 0)
        {
            std::memmove(_buffer, _buffer + _begin_position, unread);
        }
        _begin_position = 0;
        _end_position = unread;
    }

    void StageBase::clear()
    {
        _begin_position = 0;
        _end_position = 0;
    }

    void StageBase::limit(size_t capacity)
    {
        assert(_end_position == _begin_position);
        _capacity = capacity > _maximum ? _maximum : capacity;
        clear();
    }

    Stage::Stage()
        : StageStorage()
        , StageBase(Span<char>{ nullptr, 0 })
    {
    }

    Stage::Stage(size_t maximum)
        : StageStorage()
        , StageBase(Span<char>{ nullptr, 0 })
    {
        reserve(maximum);
    }

    void Stage::reserve(size_t maximum)
    {
        if (maximum <= bytes.size()) { return; }
        assert(consumer().readable() == 0);
        bytes.resize(maximum);
        bind(Span<char>{ bytes.data(), bytes.size() });
    }
}

#include <string>

namespace kiotty::net::implementation
{
    namespace
    {
        struct ByteRange
        {
            unsigned char low;
            unsigned char high;
        };

        constexpr ByteRange     CONTINUATION{ 0x80, 0xBF };
        constexpr unsigned char ASCII_END = 0x80;
        constexpr char          UPPER_TO_LOWER = 'a' - 'A';

        size_t        measureSequence(Span<const char> rest);
        size_t        sequenceLength(unsigned char lead);
        ByteRange     secondByteRange(unsigned char lead);
        unsigned char byteOf(char character);
        char          lowerOf(char character);
    }

    TextResult parseText(const char* text, size_t max_length)
    {
        if (text == nullptr) { return TextResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT); }
        const auto scan_length = checkedAdd<size_t>(max_length, 1);
        if (!scan_length) { return TextResult::failure(scan_length.code); }
        const size_t length = strnlen(text, scan_length.value);
        if (length > max_length) { return TextResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT); }
        const Span<const char> parsed{ text, length };
        if (!isUtf8(parsed)) { return TextResult::failure(KIOTTY_NET_CODE_INVALID_ENCODING); }
        return TextResult::success(parsed);
    }

    bool equalsIgnoreCase(Span<const char> left, Span<const char> right)
    {
        if (left.length != right.length) { return false; }
        for (size_t i = 0; i < left.length; ++i)
        {
            if (lowerOf(left[i]) != lowerOf(right[i])) { return false; }
        }
        return true;
    }

    bool isUtf8(Span<const char> text)
    {
        size_t position = 0;
        while (position < text.length)
        {
            const size_t length = measureSequence(text.skip(position));
            if (length == 0) { return false; }
            position += length;
        }
        return true;
    }

    namespace
    {
        size_t measureSequence(Span<const char> rest)
        {
            const unsigned char lead = byteOf(rest[0]);
            const size_t length = sequenceLength(lead);
            if (length == 0 || length > rest.length) { return 0; }
            const ByteRange second = secondByteRange(lead);
            for (size_t i = 1; i < length; ++i)
            {
                const ByteRange range = i == 1 ? second : CONTINUATION;
                const unsigned char byte = byteOf(rest[i]);
                if (byte < range.low || byte > range.high) { return 0; }
            }
            return length;
        }

        size_t sequenceLength(unsigned char lead)
        {
            if (lead < ASCII_END) { return 1; }
            if (lead >= 0xC2 && lead <= 0xDF) { return 2; }
            if (lead >= 0xE0 && lead <= 0xEF) { return 3; }
            if (lead >= 0xF0 && lead <= 0xF4) { return 4; }
            return 0;
        }

        ByteRange secondByteRange(unsigned char lead)
        {
            if (lead == 0xE0) { return ByteRange{ 0xA0, 0xBF }; }
            if (lead == 0xED) { return ByteRange{ 0x80, 0x9F }; }
            if (lead == 0xF0) { return ByteRange{ 0x90, 0xBF }; }
            if (lead == 0xF4) { return ByteRange{ 0x80, 0x8F }; }
            return CONTINUATION;
        }

        unsigned char byteOf(char character)
        {
            return static_cast<unsigned char>(character);
        }

        char lowerOf(char character)
        {
            const bool is_upper = character >= 'A' && character <= 'Z';
            if (!is_upper) { return character; }
            return static_cast<char>(character + UPPER_TO_LOWER);
        }
    }

    Span<const char> literalOf(const char* text)
    {
        return Span<const char>{ text, std::char_traits<char>::length(text) };
    }
}

#ifndef KIOTTY_NET_INTERNAL_CORE_SHA1_H
#define KIOTTY_NET_INTERNAL_CORE_SHA1_H

#include <cstddef>
#include <cstdint>

namespace kiotty::net::implementation
{
    inline constexpr size_t SHA1_DIGEST_BYTES = 20;

    struct Sha1Digest
    {
        uint8_t bytes[SHA1_DIGEST_BYTES];
    };

    Sha1Digest sha1Of(Span<const char> first, Span<const char> second);
}

#endif

#ifndef KIOTTY_NET_INTERNAL_CORE_BYTES_H
#define KIOTTY_NET_INTERNAL_CORE_BYTES_H

#include <cstdint>

namespace kiotty::net::implementation
{
    inline constexpr uint32_t BITS_PER_BYTE = 8;
    inline constexpr uint16_t BYTE_MASK = 0xFF;
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr size_t   BLOCK_BYTES = 64;
        constexpr size_t   LENGTH_BYTES = 8;
        constexpr size_t   ROUNDS = 80;
        constexpr size_t   ROUNDS_PER_STAGE = 20;
        constexpr size_t   BLOCK_WORDS = 16;
        constexpr size_t   STATE_WORDS = 5;
        constexpr size_t   WORD_BYTES = 4;
        constexpr uint8_t  END_MARK = 0x80;
        constexpr uint32_t WORD_BITS = 32;
        constexpr uint32_t INITIAL[STATE_WORDS] = {
            0x67452301u, 0xEFCDAB89u, 0x98BADCFEu, 0x10325476u, 0xC3D2E1F0u,
        };
        constexpr uint32_t STAGE_CONSTANTS[ROUNDS / ROUNDS_PER_STAGE] = {
            0x5A827999u, 0x6ED9EBA1u, 0x8F1BBCDCu, 0xCA62C1D6u,
        };

        struct Sha1State
        {
            uint32_t words[STATE_WORDS];
            uint8_t  block[BLOCK_BYTES];
            size_t   filled;
            uint64_t total;
        };

        uint32_t rotateLeft(uint32_t value, uint32_t count);
        uint32_t mixOf(size_t round, uint32_t b, uint32_t c, uint32_t d);
        uint32_t wordAt(const uint8_t (&block)[BLOCK_BYTES], size_t index);
        void     compress(Sha1State& state);
        void     absorb(Sha1State& state, Span<const char> data);
        void     absorbByte(Sha1State& state, uint8_t byte);
        void     finish(Sha1State& state);
    }

    Sha1Digest sha1Of(Span<const char> first, Span<const char> second)
    {
        Sha1State state{};
        for (size_t i = 0; i < STATE_WORDS; ++i) { state.words[i] = INITIAL[i]; }
        absorb(state, first);
        absorb(state, second);
        finish(state);
        Sha1Digest digest{};
        for (size_t i = 0; i < SHA1_DIGEST_BYTES; ++i)
        {
            const uint32_t byte_in_word = static_cast<uint32_t>(WORD_BYTES - 1 - i % WORD_BYTES);
            const uint32_t word = state.words[i / WORD_BYTES];
            digest.bytes[i] = static_cast<uint8_t>(word >> (byte_in_word * BITS_PER_BYTE));
        }
        return digest;
    }

    namespace
    {
        uint32_t rotateLeft(uint32_t value, uint32_t count)
        {
            return (value << count) | (value >> (WORD_BITS - count));
        }

        uint32_t mixOf(size_t round, uint32_t b, uint32_t c, uint32_t d)
        {
            const size_t stage = round / ROUNDS_PER_STAGE;
            if (stage == 0) { return (b & c) | (~b & d); }
            if (stage == 2) { return (b & c) | (b & d) | (c & d); }
            return b ^ c ^ d;
        }

        uint32_t wordAt(const uint8_t (&block)[BLOCK_BYTES], size_t index)
        {
            uint32_t word = 0;
            for (size_t i = 0; i < WORD_BYTES; ++i)
            {
                word = (word << BITS_PER_BYTE) | block[index * WORD_BYTES + i];
            }
            return word;
        }

        void compress(Sha1State& state)
        {
            uint32_t schedule[ROUNDS] = {};
            for (size_t i = 0; i < BLOCK_WORDS; ++i) { schedule[i] = wordAt(state.block, i); }
            for (size_t i = BLOCK_WORDS; i < ROUNDS; ++i)
            {
                const uint32_t newer = schedule[i - 3] ^ schedule[i - 8];
                const uint32_t older = schedule[i - 14] ^ schedule[i - 16];
                const uint32_t mixed = newer ^ older;
                schedule[i] = rotateLeft(mixed, 1);
            }
            uint32_t v[STATE_WORDS] = {};
            for (size_t i = 0; i < STATE_WORDS; ++i) { v[i] = state.words[i]; }
            for (size_t round = 0; round < ROUNDS; ++round)
            {
                const uint32_t constant = STAGE_CONSTANTS[round / ROUNDS_PER_STAGE];
                const uint32_t mixed = mixOf(round, v[1], v[2], v[3]);
                const uint32_t rotated = rotateLeft(v[0], 5);
                const uint32_t next = rotated + mixed + v[4] + constant + schedule[round];
                v[4] = v[3];
                v[3] = v[2];
                v[2] = rotateLeft(v[1], 30);
                v[1] = v[0];
                v[0] = next;
            }
            for (size_t i = 0; i < STATE_WORDS; ++i) { state.words[i] += v[i]; }
            state.filled = 0;
        }

        void absorbByte(Sha1State& state, uint8_t byte)
        {
            state.block[state.filled] = byte;
            state.filled += 1;
            if (state.filled == BLOCK_BYTES) { compress(state); }
        }

        void absorb(Sha1State& state, Span<const char> data)
        {
            for (size_t i = 0; i < data.length; ++i)
            {
                absorbByte(state, static_cast<uint8_t>(data[i]));
            }
            state.total += data.length;
        }

        void finish(Sha1State& state)
        {
            const uint64_t bits = state.total * BITS_PER_BYTE;
            absorbByte(state, END_MARK);
            while (state.filled != BLOCK_BYTES - LENGTH_BYTES) { absorbByte(state, 0); }
            for (size_t i = 0; i < LENGTH_BYTES; ++i)
            {
                const uint64_t shift = (LENGTH_BYTES - 1 - i) * BITS_PER_BYTE;
                absorbByte(state, static_cast<uint8_t>(bits >> shift));
            }
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_CORE_BASE64_H
#define KIOTTY_NET_INTERNAL_CORE_BASE64_H

#include <cstddef>
#include <cstdint>

namespace kiotty::net::implementation
{
    using EncodedResult = Result<size_t, KiottyNetCode>;

    size_t        base64LengthOf(size_t length);
    EncodedResult encodeBase64(Span<const uint8_t> input, Span<char> target);
    bool          isBase64Text(Span<const char> text);
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr char     ALPHABET[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                                    "abcdefghijklmnopqrstuvwxyz0123456789+/";
        constexpr char     PAD = '=';
        constexpr size_t   GROUP_BYTES = 3;
        constexpr size_t   GROUP_CHARACTERS = 4;
        constexpr size_t   MAX_PADDING = 2;
        constexpr uint32_t BITS_PER_CHARACTER = 6;
        constexpr uint32_t CHARACTER_MASK = 0x3F;

        void encodeGroup(Span<const uint8_t> group, Span<char> target);
        bool isAlphabetCharacter(char character);
    }

    size_t base64LengthOf(size_t length)
    {
        return (length + GROUP_BYTES - 1) / GROUP_BYTES * GROUP_CHARACTERS;
    }

    EncodedResult encodeBase64(Span<const uint8_t> input, Span<char> target)
    {
        const size_t length = base64LengthOf(input.length);
        if (length > target.length) { return EncodedResult::failure(KIOTTY_NET_CODE_BUFFER_FULL); }
        for (size_t i = 0; i < input.length; i += GROUP_BYTES)
        {
            const Span<const uint8_t> rest = input.skip(i);
            const size_t taken = rest.length < GROUP_BYTES ? rest.length : GROUP_BYTES;
            const Span<const uint8_t> group{ rest.data, taken };
            encodeGroup(group, target.skip(i / GROUP_BYTES * GROUP_CHARACTERS));
        }
        return EncodedResult::success(length);
    }

    bool isBase64Text(Span<const char> text)
    {
        if (text.length % GROUP_CHARACTERS != 0) { return false; }
        size_t padding = 0;
        for (size_t i = 0; i < text.length; ++i)
        {
            const bool is_pad = text[i] == PAD;
            const bool is_after_pad = !is_pad && padding > 0;
            const bool is_known = is_pad || isAlphabetCharacter(text[i]);
            if (is_after_pad || !is_known) { return false; }
            padding += is_pad ? 1 : 0;
        }
        return padding <= MAX_PADDING;
    }

    namespace
    {
        void encodeGroup(Span<const uint8_t> group, Span<char> target)
        {
            uint32_t bits = 0;
            for (size_t i = 0; i < GROUP_BYTES; ++i)
            {
                const uint32_t byte = i < group.length ? group[i] : 0u;
                bits = (bits << BITS_PER_BYTE) | byte;
            }
            for (size_t i = 0; i < GROUP_CHARACTERS; ++i)
            {
                const uint32_t place = static_cast<uint32_t>(GROUP_CHARACTERS - 1 - i);
                const uint32_t shift = place * BITS_PER_CHARACTER;
                const bool is_padding = i > group.length;
                target[i] = is_padding ? PAD : ALPHABET[(bits >> shift) & CHARACTER_MASK];
            }
        }

        bool isAlphabetCharacter(char character)
        {
            const bool is_upper = character >= 'A' && character <= 'Z';
            const bool is_lower = character >= 'a' && character <= 'z';
            const bool is_digit = character >= '0' && character <= '9';
            return is_upper || is_lower || is_digit || character == '+' || character == '/';
        }
    }
}

