#ifndef KIOTTY_NET_INTERNAL_BASE_DATA_INFRA_ERROR_SOCKET_ERROR_H
#define KIOTTY_NET_INTERNAL_BASE_DATA_INFRA_ERROR_SOCKET_ERROR_H

namespace kiotty::net::implementation
{
    struct SocketErrorEntry
    {
        int        os_error;
        SocketCode code;
    };

    Span<const SocketErrorEntry> socketErrorTable();
    SocketCode                   toSocketCode(int os_error);
    SocketCode                   lastSocketCode();
}

#endif

namespace kiotty::net::implementation
{
    SocketCode toSocketCode(int os_error)
    {
        if (os_error == 0) { return SocketCode::SUCCESS; }
        const Span<const SocketErrorEntry> table = socketErrorTable();
        for (const SocketErrorEntry& entry : table)
        {
            if (entry.os_error == os_error) { return entry.code; }
        }
        return SocketCode::UNKNOWN;
    }
}

