namespace kiotty::net::implementation
{
    namespace
    {
        TransferResult receiveWith(const ActiveSocket& socket, Span<char> buffer, int flags);
    }

    TransferResult send(const ActiveSocket& socket, Span<const char> data)
    {
        if (!socket.valid()) { return TransferResult::failure(SocketCode::INVALID_ARGUMENT); }
        const int sent = ::send(socketOf(socket.handle()), data.data, clampLength(data.length), 0);
        if (sent == SOCKET_ERROR) { return TransferResult::failure(lastSocketCode()); }
        return TransferResult::success(static_cast<size_t>(sent));
    }

    TransferResult receive(const ActiveSocket& socket, Span<char> buffer)
    {
        return receiveWith(socket, buffer, 0);
    }

    TransferResult peek(const ActiveSocket& socket, Span<char> buffer)
    {
        return receiveWith(socket, buffer, MSG_PEEK);
    }

    SocketCode waitReadable(const ActiveSocket& socket, uint32_t timeout_milliseconds)
    {
        if (!socket.valid()) { return SocketCode::INVALID_ARGUMENT; }
        const SOCKET native = socketOf(socket.handle());
        const SocketTraits traits = socket.traits();
        return waitReady(native, WaitDirection::READ, timeout_milliseconds, traits.stop);
    }

    SocketCode waitWritable(const ActiveSocket& socket, uint32_t timeout_milliseconds)
    {
        if (!socket.valid()) { return SocketCode::INVALID_ARGUMENT; }
        const SOCKET native = socketOf(socket.handle());
        const SocketTraits traits = socket.traits();
        return waitReady(native, WaitDirection::WRITE, timeout_milliseconds, traits.stop);
    }

    SocketCode shutdownWrite(const ActiveSocket& socket)
    {
        if (!socket.valid()) { return SocketCode::INVALID_ARGUMENT; }
        const int done = ::shutdown(socketOf(socket.handle()), SD_SEND);
        if (done != 0) { return lastSocketCode(); }
        return SocketCode::SUCCESS;
    }

    SocketCode configureNoDelay(const ActiveSocket& socket, NoDelay no_delay)
    {
        if (!socket.valid()) { return SocketCode::INVALID_ARGUMENT; }
        const bool is_pipe = socket.traits().transport == KIOTTY_NET_TRANSPORT_PIPE;
        if (is_pipe) { return SocketCode::SUCCESS; }
        const BOOL value = no_delay == NoDelay::ENABLED ? TRUE : FALSE;
        const char* option = reinterpret_cast<const char*>(&value);
        const SOCKET native = socketOf(socket.handle());
        const int set = ::setsockopt(native, IPPROTO_TCP, TCP_NODELAY, option, sizeof(value));
        if (set != 0) { return lastSocketCode(); }
        return SocketCode::SUCCESS;
    }

    namespace
    {
        TransferResult receiveWith(const ActiveSocket& socket, Span<char> buffer, int flags)
        {
            if (!socket.valid()) { return TransferResult::failure(SocketCode::INVALID_ARGUMENT); }
            const SOCKET native = socketOf(socket.handle());
            const int length = clampLength(buffer.length);
            const int received = ::recv(native, buffer.data, length, flags);
            if (received == SOCKET_ERROR) { return TransferResult::failure(lastSocketCode()); }
            const bool is_closed = received == 0 && buffer.length > 0;
            if (is_closed) { return TransferResult::failure(SocketCode::CLOSED); }
            return TransferResult::success(static_cast<size_t>(received));
        }
    }
}

#endif

#if !defined(_WIN32)

#include <fcntl.h>
#include <unistd.h>

#include <cerrno>

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr size_t DRAIN_BYTES = 64;
        constexpr int    PIPE_ENDS = 2;

        SocketCode prepareEnd(int descriptor);
    }

    SocketCode StopSignal::open()
    {
        if (_reader != INVALID_SOCKET_HANDLE) { return SocketCode::SUCCESS; }
        int ends[PIPE_ENDS] = { -1, -1 };
        if (::pipe(ends) != 0) { return lastSocketCode(); }
        _reader = ends[0];
        _writer = ends[1];
        const SocketCode reader = prepareEnd(ends[0]);
        const SocketCode writer = prepareEnd(ends[1]);
        const bool is_prepared = reader == SocketCode::SUCCESS && writer == SocketCode::SUCCESS;
        if (is_prepared) { return SocketCode::SUCCESS; }
        close();
        return reader != SocketCode::SUCCESS ? reader : writer;
    }

    void StopSignal::drain() const
    {
        if (_reader == INVALID_SOCKET_HANDLE) { return; }
        char sink[DRAIN_BYTES]{};
        for (;;)
        {
            const ssize_t taken = ::read(static_cast<int>(_reader), sink, sizeof(sink));
            const bool is_interrupted = taken < 0 && errno == EINTR;
            if (taken <= 0 && !is_interrupted) { return; }
        }
    }

    void StopSignal::close()
    {
        if (_reader != INVALID_SOCKET_HANDLE) { ::close(static_cast<int>(_reader)); }
        if (_writer != INVALID_SOCKET_HANDLE) { ::close(static_cast<int>(_writer)); }
        _reader = INVALID_SOCKET_HANDLE;
        _writer = INVALID_SOCKET_HANDLE;
    }

    void StopSignal::notify() const
    {
        if (_writer == INVALID_SOCKET_HANDLE) { return; }
        const char wake = 1;
        for (;;)
        {
            const ssize_t written = ::write(static_cast<int>(_writer), &wake, sizeof(wake));
            if (written >= 0 || errno != EINTR) { return; }
        }
    }

    namespace
    {
        SocketCode prepareEnd(int descriptor)
        {
            const int flags = ::fcntl(descriptor, F_GETFL, 0);
            if (flags < 0) { return lastSocketCode(); }
            const int non_blocking = ::fcntl(descriptor, F_SETFL, flags | O_NONBLOCK);
            if (non_blocking < 0) { return lastSocketCode(); }
            const int close_on_exec = ::fcntl(descriptor, F_SETFD, FD_CLOEXEC);
            if (close_on_exec < 0) { return lastSocketCode(); }
            return SocketCode::SUCCESS;
        }
    }
}

#endif

