        constexpr KiottyNetSpan LINE_END_SPAN{ LINE_END, 2 };
        constexpr int32_t       SERVER_ERROR = KIOTTY_NET_HTTP_STATUS_INTERNAL_SERVER_ERROR;

        size_t                      lineLimitOf(const HttpSessionHost& host);
