namespace kiotty::net::implementation
{
    namespace
    {
        struct HeadCursor
        {
            Span<char> buffer;
            size_t     length;
        };

        struct HeadPlan
        {
            size_t line_count;
            bool   has_content_type;
            bool   has_content_length;
            bool   is_chunked;
        };

        constexpr size_t        HOST_LINE_COUNT = 1;
        constexpr char          OPEN_BRACKET[] = "[";
        constexpr char          CLOSE_BRACKET[] = "]";
        constexpr char          PORT_SEPARATOR[] = ":";
        constexpr char          FIELD_SEPARATOR[] = ": ";
        constexpr char          SPACE[] = " ";
        constexpr char          VERSION_LINE_END[] = " HTTP/1.1\r\n";
        constexpr char          HOST[] = "Host";
        constexpr char          PIPE_HOST[] = "localhost";
        constexpr char          CONTENT_TYPE[] = "Content-Type";
        constexpr char          CHUNKED_CODING[] = "chunked";

        bool          isHostText(Span<const char> host);
        bool          isLiteralV6(Span<const char> host);
        KiottyNetCode checkHeadParts(const RequestHead& head);
        HeadPlan      planHead(const RequestHead& head);
        size_t        countSharedSent(const RequestHead& head, const HeadPlan& plan);
        bool isSharedSent(const KiottyNetHttpHeader& header,
                          const RequestHead& head,
                          const HeadPlan& plan);
        bool hasHeaderNamed(Span<const KiottyNetHttpHeader> headers, Span<const char> name);
        bool needsLength(KiottyNetHttpMethod method);
        bool writeStartLines(HeadCursor& cursor, const RequestHead& head);
        bool writeSharedHeaders(HeadCursor& cursor, const RequestHead& head, const HeadPlan& plan);
        bool writeExtraHeaders(HeadCursor& cursor, Span<const KiottyNetHttpHeader> headers);
        bool writeBodyFields(HeadCursor& cursor, const RequestHead& head, const HeadPlan& plan);
        bool putField(HeadCursor& cursor, Span<const char> name, Span<const char> value);
        bool appendText(HeadCursor& cursor, Span<const char> text);
    }

    HostFieldResult buildHostField(Span<const char> host, uint16_t port, uint16_t default_port)
    {
        if (!isHostText(host)) { return HostFieldResult::failure(INVALID); }
        const bool is_literal_v6 = isLiteralV6(host);
        const bool has_port = port != default_port;
        const DecimalText digits = decimalOf(port);
        HostField field;
        bool is_written = !is_literal_v6 || field.append(textOf(OPEN_BRACKET));
        is_written = is_written && field.append(host);
        is_written = is_written && (!is_literal_v6 || field.append(textOf(CLOSE_BRACKET)));
        is_written = is_written && (!has_port || field.append(textOf(PORT_SEPARATOR)));
        is_written = is_written && (!has_port || field.append(digits.span()));
        if (!is_written) { return HostFieldResult::failure(INVALID); }
        return HostFieldResult::success(field);
    }

    HostFieldResult hostFieldOf(const KiottyNetAddress& address, uint16_t default_port)
    {
        const bool is_pipe = address.transport == KIOTTY_NET_TRANSPORT_PIPE;
        if (is_pipe) { return buildHostField(textOf(PIPE_HOST), default_port, default_port); }
        return buildHostField(textOf(address.host), address.port, default_port);
    }

    HeadLengthResult writeRequestHead(Span<char> buffer, const RequestHead& head)
    {
        const KiottyNetCode checked = checkHeadParts(head);
        if (checked != KIOTTY_NET_CODE_SUCCESS) { return HeadLengthResult::failure(checked); }
        const HeadPlan plan = planHead(head);
        const bool is_table_full = plan.line_count > head.max_headers;
        if (is_table_full) { return HeadLengthResult::failure(KIOTTY_NET_CODE_TABLE_FULL); }
        HeadCursor cursor{ buffer, 0 };
        bool is_written = writeStartLines(cursor, head);
        is_written = is_written && writeSharedHeaders(cursor, head, plan);
        is_written = is_written && writeExtraHeaders(cursor, head.extra_headers);
        is_written = is_written && writeBodyFields(cursor, head, plan);
        is_written = is_written && appendText(cursor, textOf(LINE_END));
        if (!is_written) { return HeadLengthResult::failure(KIOTTY_NET_CODE_REQUEST_TOO_LARGE); }
        return HeadLengthResult::success(cursor.length);
    }

    namespace
    {
        bool isHostText(Span<const char> host)
        {
            if (host.empty()) { return false; }
            for (size_t i = 0; i < host.length; ++i)
            {
                if (!isVisibleCharacter(host[i])) { return false; }
            }
            return true;
        }

        bool isLiteralV6(Span<const char> host)
        {
            const bool has_colon = findCharacter(host, ':', 0) < host.length;
            const bool is_bracketed = host[0] == OPEN_BRACKET[0];
            return has_colon && !is_bracketed;
        }

        KiottyNetCode checkHeadParts(const RequestHead& head)
        {
            const bool is_method = methodTextOf(head.method).length > 0;
            if (!is_method) { return INVALID; }
            const KiottyNetCode path = checkRequestPath(head.method, head.path);
            if (path != KIOTTY_NET_CODE_SUCCESS) { return path; }
            const bool is_table_full = head.extra_headers.length > head.max_headers;
            if (is_table_full) { return KIOTTY_NET_CODE_TABLE_FULL; }
            for (const KiottyNetHttpHeader& header : head.extra_headers)
            {
                const KiottyNetCode code = checkRequestHeader(header);
                if (code != KIOTTY_NET_CODE_SUCCESS) { return code; }
            }
            return KIOTTY_NET_CODE_SUCCESS;
        }

        HeadPlan planHead(const RequestHead& head)
        {
            const bool is_chunked = head.body_length == CHUNKED_BODY_LENGTH;
            const bool has_body = head.body_length > 0;
            const bool is_custom = head.type == KIOTTY_NET_HTTP_CONTENT_TYPE_CUSTOM;
            const bool has_own_type = hasHeaderNamed(head.extra_headers, textOf(CONTENT_TYPE));
            const bool has_content_type = has_body && !is_custom && !has_own_type;
            const bool is_counted = has_body || needsLength(head.method);
            const bool has_content_length = is_counted && !is_chunked;
            HeadPlan plan{ 0, has_content_type, has_content_length, is_chunked };
            plan.line_count = HOST_LINE_COUNT + countSharedSent(head, plan);
            plan.line_count += head.extra_headers.length;
            plan.line_count += has_content_type ? 1 : 0;
            plan.line_count += has_content_length || is_chunked ? 1 : 0;
            return plan;
        }

        size_t countSharedSent(const RequestHead& head, const HeadPlan& plan)
        {
            size_t count = 0;
            for (const KiottyNetHttpHeader& header : head.shared_headers)
            {
                count += isSharedSent(header, head, plan) ? 1 : 0;
            }
            return count;
        }

        bool isSharedSent(const KiottyNetHttpHeader& header,
                          const RequestHead& head,
                          const HeadPlan& plan)
        {
            const Span<const char> name = spanOf(header.name);
            if (hasHeaderNamed(head.extra_headers, name)) { return false; }
            const bool is_type = equalsLiteralIgnoreCase(name, CONTENT_TYPE);
            return !(is_type && plan.has_content_type);
        }

        bool hasHeaderNamed(Span<const KiottyNetHttpHeader> headers, Span<const char> name)
        {
            for (const KiottyNetHttpHeader& header : headers)
            {
                if (equalsIgnoreCase(spanOf(header.name), name)) { return true; }
            }
            return false;
        }

        bool needsLength(KiottyNetHttpMethod method)
        {
            const bool is_post = method == KIOTTY_NET_HTTP_METHOD_POST;
            const bool is_put = method == KIOTTY_NET_HTTP_METHOD_PUT;
            return is_post || is_put || method == KIOTTY_NET_HTTP_METHOD_PATCH;
        }

        bool writeStartLines(HeadCursor& cursor, const RequestHead& head)
        {
            bool is_written = appendText(cursor, methodTextOf(head.method));
            is_written = is_written && appendText(cursor, textOf(SPACE));
            is_written = is_written && appendText(cursor, head.path);
            is_written = is_written && appendText(cursor, textOf(VERSION_LINE_END));
            return is_written && putField(cursor, textOf(HOST), head.host_field);
        }

        bool writeSharedHeaders(HeadCursor& cursor, const RequestHead& head, const HeadPlan& plan)
        {
            for (const KiottyNetHttpHeader& header : head.shared_headers)
            {
                const bool is_sent = isSharedSent(header, head, plan);
                const Span<const char> name = spanOf(header.name);
                const bool is_written = !is_sent || putField(cursor, name, spanOf(header.value));
                if (!is_written) { return false; }
            }
            return true;
        }

        bool writeExtraHeaders(HeadCursor& cursor, Span<const KiottyNetHttpHeader> headers)
        {
            for (const KiottyNetHttpHeader& header : headers)
            {
                const Span<const char> value = trimWhitespace(spanOf(header.value));
                const bool is_written = putField(cursor, spanOf(header.name), value);
                if (!is_written) { return false; }
            }
            return true;
        }

        bool writeBodyFields(HeadCursor& cursor, const RequestHead& head, const HeadPlan& plan)
        {
            const Span<const char> type = contentTypeTextOf(head.type);
            const DecimalText length = decimalOf(head.body_length);
            const bool is_typed = !plan.has_content_type
                                  || putField(cursor, textOf(CONTENT_TYPE), type);
            if (!is_typed) { return false; }
            if (plan.is_chunked)
            {
                return putField(cursor, textOf(TRANSFER_ENCODING), textOf(CHUNKED_CODING));
            }
            return !plan.has_content_length
                   || putField(cursor, textOf(CONTENT_LENGTH), length.span());
        }

        bool putField(HeadCursor& cursor, Span<const char> name, Span<const char> value)
        {
            bool is_written = appendText(cursor, name);
            is_written = is_written && appendText(cursor, textOf(FIELD_SEPARATOR));
            is_written = is_written && appendText(cursor, value);
            return is_written && appendText(cursor, textOf(LINE_END));
        }

        bool appendText(HeadCursor& cursor, Span<const char> text)
        {
            const Span<char> room = cursor.buffer.skip(cursor.length);
            if (!room.copyFrom(text)) { return false; }
            cursor.length += text.length;
            return true;
        }
    }
}

namespace kiotty::net::implementation
{
    HttpUpload idleUpload()
    {
        return HttpUpload{ 0, KIOTTY_NET_HTTP_METHOD_GET, UploadMode::IDLE };
    }

    HttpUpload startUpload(KiottyNetHttpMethod method, uint64_t body_length)
    {
        const bool is_chunked = body_length == CHUNKED_BODY_LENGTH;
        if (is_chunked) { return HttpUpload{ 0, method, UploadMode::CHUNKED }; }
        return HttpUpload{ body_length, method, UploadMode::LENGTH };
    }

    KiottyNetCode checkUploadPiece(const HttpUpload& upload, size_t length)
    {
        if (upload.mode == UploadMode::IDLE) { return INVALID; }
        if (length > RESULT_MAXIMUM_BYTES) { return INVALID; }
        const bool is_counted = upload.mode == UploadMode::LENGTH;
        const bool is_over = is_counted && length > upload.left;
        if (is_over) { return INVALID; }
        return KIOTTY_NET_CODE_SUCCESS;
    }

    HttpUpload takeUploadPiece(const HttpUpload& upload, size_t length)
    {
        HttpUpload taken = upload;
        const bool is_counted = upload.mode == UploadMode::LENGTH;
        if (is_counted) { taken.left -= length; }
        return taken;
    }

    KiottyNetCode checkUploadEnd(const HttpUpload& upload)
    {
        if (upload.mode == UploadMode::IDLE) { return INVALID; }
        const bool is_short = upload.mode == UploadMode::LENGTH && upload.left > 0;
        if (is_short) { return INVALID; }
        return KIOTTY_NET_CODE_SUCCESS;
    }
}

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr char          ALLOW[] = "Allow";
        constexpr char          LIST_SEPARATOR = ',';
        constexpr KiottyNetSpan NO_HEADER{ nullptr, 0 };

        uint32_t methodsOfList(Span<const char> list);
        uint32_t methodBitOf(Span<const char> token);
    }

    KiottyNetSpan findReplyHeader(Span<const KiottyNetHttpHeader> headers, Span<const char> name)
    {
        for (const KiottyNetHttpHeader& header : headers)
        {
            if (equalsIgnoreCase(spanOf(header.name), name)) { return header.value; }
        }
        return NO_HEADER;
    }

    uint32_t allowedMethodsOf(Span<const KiottyNetHttpHeader> headers)
    {
        uint32_t methods = 0;
        for (const KiottyNetHttpHeader& header : headers)
        {
            const bool is_allow = equalsLiteralIgnoreCase(spanOf(header.name), ALLOW);
            methods |= is_allow ? methodsOfList(spanOf(header.value)) : 0U;
        }
        return methods;
    }

    namespace
    {
        uint32_t methodsOfList(Span<const char> list)
        {
            uint32_t methods = 0;
            size_t start = 0;
            while (start <= list.length)
            {
                const size_t comma = findCharacter(list, LIST_SEPARATOR, start);
                const Span<const char> item{ list.data + start, comma - start };
                methods |= methodBitOf(trimWhitespace(item));
                start = comma + 1;
            }
            return methods;
        }

        uint32_t methodBitOf(Span<const char> token)
        {
            for (int32_t index = 0; index < KIOTTY_NET_HTTP_METHOD_COUNT; ++index)
            {
                const KiottyNetHttpMethod method = static_cast<KiottyNetHttpMethod>(index);
                const Span<const char> text = methodTextOf(method);
                const bool is_same = text.length > 0 && equalsLiteral(token, text.data);
                if (is_same) { return KIOTTY_NET_HTTP_METHOD_BIT(method); }
            }
            return 0;
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_FRAME_WEBSOCKET_FRAME_PARSER_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_FRAME_WEBSOCKET_FRAME_PARSER_H

#include <cstddef>
#include <cstdint>

namespace kiotty::net::implementation
{
    using FrameStartResult = Result<FrameStart, KiottyNetWebSocketStatus>;
    using FrameLengthResult = Result<uint64_t, KiottyNetWebSocketStatus>;

    FrameStartResult  parseFrameStart(Span<const char> bytes);
    size_t            extendedLengthBytesOf(uint8_t length_code);
    FrameLengthResult parseExtendedLength(Span<const char> bytes);
    MaskKey           parseMaskKey(Span<const char> bytes);
    bool              isControl(FrameOpcode opcode);
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr uint8_t  RESERVED_BITS = 0x70;
        constexpr uint8_t  OPCODE_BITS = 0x0F;
        constexpr uint8_t  CONTROL_BIT = 0x08;
        constexpr uint8_t  KNOWN_OPCODES[] = { 0x0, 0x1, 0x2, 0x8, 0x9, 0xA };
        constexpr uint8_t  LENGTH_BITS = 0x7F;
        constexpr uint64_t LONG_LENGTH_TOP_BIT = 0x8000000000000000ull;

        bool     isKnownOpcode(uint8_t opcode);
        uint64_t bigEndianOf(Span<const char> bytes);
    }

    FrameStartResult parseFrameStart(Span<const char> bytes)
    {
        if (bytes.length != FRAME_START_BYTES) { return FrameStartResult::failure(CLOSE_PROTOCOL); }
        const uint8_t first = static_cast<uint8_t>(bytes[0]);
        const uint8_t second = static_cast<uint8_t>(bytes[1]);
        const uint8_t opcode = first & OPCODE_BITS;
        const bool is_reserved = (first & RESERVED_BITS) != 0;
        const bool is_known = isKnownOpcode(opcode);
        if (is_reserved || !is_known) { return FrameStartResult::failure(CLOSE_PROTOCOL); }
        const FrameStart start{
            static_cast<FrameOpcode>(opcode),
            (first & FINAL_BIT) != 0 ? FrameFinality::FINAL : FrameFinality::MORE,
            (second & MASK_BIT) != 0 ? FrameMasking::MASKED : FrameMasking::PLAIN,
            static_cast<uint8_t>(second & LENGTH_BITS),
        };
        const bool is_control = isControl(start.opcode);
        const bool is_split = start.finality == FrameFinality::MORE;
        const bool is_long = start.length_code > MAX_CONTROL_PAYLOAD_BYTES;
        const bool is_bad_control = is_control && (is_split || is_long);
        if (is_bad_control) { return FrameStartResult::failure(CLOSE_PROTOCOL); }
        return FrameStartResult::success(start);
    }

    size_t extendedLengthBytesOf(uint8_t length_code)
    {
        if (length_code == SHORT_LENGTH_CODE) { return SHORT_LENGTH_BYTES; }
        if (length_code == LONG_LENGTH_CODE) { return LONG_LENGTH_BYTES; }
        return 0;
    }

    FrameLengthResult parseExtendedLength(Span<const char> bytes)
    {
        const bool is_short = bytes.length == SHORT_LENGTH_BYTES;
        const bool is_long = bytes.length == LONG_LENGTH_BYTES;
        if (!is_short && !is_long) { return FrameLengthResult::failure(CLOSE_PROTOCOL); }
        const uint64_t length = bigEndianOf(bytes);
        const uint64_t minimum = is_short ? SHORT_LENGTH_MIN : LONG_LENGTH_MIN;
        const bool is_top_set = (length & LONG_LENGTH_TOP_BIT) != 0;
        if (length < minimum || is_top_set) { return FrameLengthResult::failure(CLOSE_PROTOCOL); }
        return FrameLengthResult::success(length);
    }

    MaskKey parseMaskKey(Span<const char> bytes)
    {
        MaskKey key{};
        for (size_t i = 0; i < MASK_KEY_BYTES && i < bytes.length; ++i)
        {
            key.bytes[i] = static_cast<uint8_t>(bytes[i]);
        }
        return key;
    }

    bool isControl(FrameOpcode opcode)
    {
        return (static_cast<uint8_t>(opcode) & CONTROL_BIT) != 0;
    }

    namespace
    {
        bool isKnownOpcode(uint8_t opcode)
        {
            for (const uint8_t known : KNOWN_OPCODES)
            {
                if (known == opcode) { return true; }
            }
            return false;
        }

        uint64_t bigEndianOf(Span<const char> bytes)
        {
            uint64_t value = 0;
            for (size_t i = 0; i < bytes.length; ++i)
            {
                value = (value << BITS_PER_BYTE) | static_cast<uint8_t>(bytes[i]);
            }
            return value;
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_FRAME_WEBSOCKET_FRAME_BUILDER_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_FRAME_WEBSOCKET_FRAME_BUILDER_H

#include <cstdint>

namespace kiotty::net::implementation
{
    FrameHead        buildFrameHead(FrameOpcode opcode, uint64_t length);
    FrameHead        buildMaskedFrameHead(FrameOpcode opcode, uint64_t length, const MaskKey& key);
    Span<const char> headBytesOf(const FrameHead& head);
}

#endif

#include <cstddef>

namespace kiotty::net::implementation
{
    namespace
    {
        FrameHead headOf(FrameOpcode opcode, uint64_t length, uint8_t mask_bit);
        void      appendBigEndian(FrameHead& head, uint64_t value, size_t bytes);
        uint8_t   lengthCodeOf(uint64_t length);
    }

    FrameHead buildFrameHead(FrameOpcode opcode, uint64_t length)
    {
        return headOf(opcode, length, 0);
    }

    FrameHead buildMaskedFrameHead(FrameOpcode opcode, uint64_t length, const MaskKey& key)
    {
        FrameHead head = headOf(opcode, length, MASK_BIT);
        for (size_t i = 0; i < MASK_KEY_BYTES; ++i)
        {
            head.bytes[head.length + i] = static_cast<char>(key.bytes[i]);
        }
        head.length += MASK_KEY_BYTES;
        return head;
    }

    Span<const char> headBytesOf(const FrameHead& head)
    {
        return Span<const char>{ head.bytes, head.length };
    }

    namespace
    {
        FrameHead headOf(FrameOpcode opcode, uint64_t length, uint8_t mask_bit)
        {
            FrameHead head{};
            head.bytes[0] = static_cast<char>(FINAL_BIT | static_cast<uint8_t>(opcode));
            head.length = FRAME_START_BYTES;
            const bool is_small = length < SHORT_LENGTH_MIN;
            const bool is_short = !is_small && length < LONG_LENGTH_MIN;
            const uint8_t code = lengthCodeOf(length);
            head.bytes[1] = static_cast<char>(mask_bit | code);
            if (is_short) { appendBigEndian(head, length, SHORT_LENGTH_BYTES); }
            const bool is_long = !is_small && !is_short;
            if (is_long) { appendBigEndian(head, length, LONG_LENGTH_BYTES); }
            return head;
        }

        uint8_t lengthCodeOf(uint64_t length)
        {
            if (length < SHORT_LENGTH_MIN) { return static_cast<uint8_t>(length); }
            if (length < LONG_LENGTH_MIN) { return SHORT_LENGTH_CODE; }
            return LONG_LENGTH_CODE;
        }

        void appendBigEndian(FrameHead& head, uint64_t value, size_t bytes)
        {
            for (size_t i = 0; i < bytes; ++i)
            {
                const uint64_t shift = (bytes - 1 - i) * BITS_PER_BYTE;
                const uint8_t byte = static_cast<uint8_t>(value >> shift);
                head.bytes[head.length + i] = static_cast<char>(byte);
            }
            head.length += bytes;
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_FRAME_WEBSOCKET_MASK_RULES_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_FRAME_WEBSOCKET_MASK_RULES_H

#include <atomic>
#include <cstddef>
#include <cstdint>

namespace kiotty::net::implementation
{
    void    applyMask(Span<char> data, const MaskKey& key, size_t offset);
    MaskKey nextMaskKey(std::atomic<uint64_t>& state);
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr uint64_t GOLDEN_GAMMA = 0x9E3779B97F4A7C15ULL;
        constexpr uint64_t MIX_FIRST = 0xBF58476D1CE4E5B9ULL;
        constexpr uint64_t MIX_SECOND = 0x94D049BB133111EBULL;
    }

    void applyMask(Span<char> data, const MaskKey& key, size_t offset)
    {
        for (size_t i = 0; i < data.length; ++i)
        {
            const uint8_t mask = key.bytes[(offset + i) % MASK_KEY_BYTES];
            data[i] = static_cast<char>(static_cast<uint8_t>(data[i]) ^ mask);
        }
    }

    MaskKey nextMaskKey(std::atomic<uint64_t>& state)
    {
        const uint64_t drawn = state.fetch_add(GOLDEN_GAMMA) + GOLDEN_GAMMA;
        uint64_t mixed = (drawn ^ (drawn >> 30U)) * MIX_FIRST;
        mixed = (mixed ^ (mixed >> 27U)) * MIX_SECOND;
        mixed = mixed ^ (mixed >> 31U);
        MaskKey key{};
        for (size_t i = 0; i < MASK_KEY_BYTES; ++i)
        {
            key.bytes[i] = static_cast<uint8_t>(mixed >> (BITS_PER_BYTE * i));
        }
        return key;
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_CONTROL_WEBSOCKET_CLOSE_RULES_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_CONTROL_WEBSOCKET_CLOSE_RULES_H

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DOMAIN_ENTITY_WEBSOCKET_CLOSE_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DOMAIN_ENTITY_WEBSOCKET_CLOSE_H

#include <cstddef>
#include <cstdint>

namespace kiotty::net::implementation
{
    inline constexpr size_t   STATUS_BYTES = 2;
    inline constexpr uint16_t NO_STATUS = KIOTTY_NET_WEB_SOCKET_STATUS_NO_STATUS;
    inline constexpr uint16_t ABNORMAL = KIOTTY_NET_WEB_SOCKET_STATUS_ABNORMAL_CLOSURE;
    inline constexpr uint16_t GOING_AWAY = KIOTTY_NET_WEB_SOCKET_STATUS_GOING_AWAY;

    inline constexpr KiottyNetWebSocketStatus CLOSE_INVALID_PAYLOAD =
        KIOTTY_NET_WEB_SOCKET_STATUS_INVALID_PAYLOAD;

    struct ClosePayload
    {
        Span<const char> reason;
        uint16_t         status;
    };

    using CloseText = FixedString<MAX_CONTROL_PAYLOAD_BYTES + 1>;
}

#endif

#include <cstdint>

namespace kiotty::net::implementation
{
    using ClosePayloadResult = Result<ClosePayload, KiottyNetWebSocketStatus>;
    using CloseTextResult = Result<CloseText, KiottyNetCode>;

    ClosePayloadResult parseClosePayload(Span<const char> payload);
    CloseTextResult    buildClosePayload(uint16_t status, Span<const char> reason);
    bool               isSendableCloseStatus(uint16_t status);
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr uint16_t FIRST_DEFINED = 1000;
        constexpr uint16_t LAST_DEFINED = 1014;
        constexpr uint16_t FIRST_PRIVATE = 3000;
        constexpr uint16_t LAST_PRIVATE = 4999;
        constexpr uint16_t RESERVED_1004 = 1004;
    }

    ClosePayloadResult parseClosePayload(Span<const char> payload)
    {
        const Span<const char> no_reason{ nullptr, 0 };
        const ClosePayload unspecified{ no_reason, NO_STATUS };
        if (payload.empty()) { return ClosePayloadResult::success(unspecified); }
        const bool is_status_cut = payload.length < STATUS_BYTES;
        const bool is_too_long = payload.length > MAX_CONTROL_PAYLOAD_BYTES;
        if (is_status_cut || is_too_long) { return ClosePayloadResult::failure(CLOSE_PROTOCOL); }
        const uint16_t high = static_cast<uint8_t>(payload[0]);
        const uint16_t low = static_cast<uint8_t>(payload[1]);
        const uint16_t status = static_cast<uint16_t>((high << BITS_PER_BYTE) | low);
        if (!isSendableCloseStatus(status)) { return ClosePayloadResult::failure(CLOSE_PROTOCOL); }
        const Span<const char> reason = payload.skip(STATUS_BYTES);
        if (!isUtf8(reason)) { return ClosePayloadResult::failure(CLOSE_INVALID_PAYLOAD); }
        return ClosePayloadResult::success(ClosePayload{ reason, status });
    }

    CloseTextResult buildClosePayload(uint16_t status, Span<const char> reason)
    {
        const bool is_status = isSendableCloseStatus(status);
        const bool is_short = reason.length <= MAX_CONTROL_PAYLOAD_BYTES - STATUS_BYTES;
        const KiottyNetCode invalid = KIOTTY_NET_CODE_INVALID_ARGUMENT;
        if (!is_status || !is_short) { return CloseTextResult::failure(invalid); }
        if (!isUtf8(reason)) { return CloseTextResult::failure(KIOTTY_NET_CODE_INVALID_ENCODING); }
        const char bytes[STATUS_BYTES] = {
            static_cast<char>(static_cast<uint8_t>(status >> BITS_PER_BYTE)),
            static_cast<char>(static_cast<uint8_t>(status & BYTE_MASK)),
        };
        CloseText text;
        (void)text.assign(Span<const char>{ bytes, STATUS_BYTES });
        (void)text.append(reason);
        return CloseTextResult::success(text);
    }

    bool isSendableCloseStatus(uint16_t status)
    {
        const bool is_defined = status >= FIRST_DEFINED && status <= LAST_DEFINED;
        const bool is_unset = status == NO_STATUS || status == ABNORMAL;
        const bool is_reserved = status == RESERVED_1004 || is_unset;
        const bool is_private = status >= FIRST_PRIVATE && status <= LAST_PRIVATE;
        return (is_defined && !is_reserved) || is_private;
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_HANDSHAKE_WEBSOCKET_KEY_RULES_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_HANDSHAKE_WEBSOCKET_KEY_RULES_H

namespace kiotty::net::implementation
{
    bool       isWebSocketKey(Span<const char> key);
    AcceptText acceptOf(Span<const char> key);
}

#endif

#include <cstdint>

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr char   ACCEPT_GUID[] = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        constexpr size_t KEY_PADDING = 2;
    }

    bool isWebSocketKey(Span<const char> key)
    {
        if (key.length != WEB_SOCKET_KEY_LENGTH) { return false; }
        if (!isBase64Text(key)) { return false; }
        const bool is_last_pad = key[WEB_SOCKET_KEY_LENGTH - 1] == '=';
        return is_last_pad && key[WEB_SOCKET_KEY_LENGTH - KEY_PADDING] == '=';
    }

    AcceptText acceptOf(Span<const char> key)
    {
        const Span<const char> guid{ ACCEPT_GUID, sizeof(ACCEPT_GUID) - 1 };
        const Sha1Digest digest = sha1Of(key, guid);
        char encoded[WEB_SOCKET_ACCEPT_LENGTH] = {};
        const Span<const uint8_t> input{ digest.bytes, SHA1_DIGEST_BYTES };
        (void)encodeBase64(input, Span<char>{ encoded, WEB_SOCKET_ACCEPT_LENGTH });
        AcceptText text;
        (void)text.assign(Span<const char>{ encoded, WEB_SOCKET_ACCEPT_LENGTH });
        return text;
    }
}

namespace kiotty::net::implementation
{
    KiottyNetCode pushFrame(PushLane& lane,
                            const SocketLink& link,
                            FrameOpcode opcode,
                            Span<const char> payload)
    {
        return lane.push(link.connection.load(), opcode, payload);
    }

    KiottyNetCode pushClose(PushLane& lane,
                            SocketLink& link,
                            uint16_t status,
                            Span<const char> reason)
    {
        const CloseTextResult payload = buildClosePayload(status, reason);
        if (!payload) { return payload.code; }
        uint16_t open = 0;
        const bool is_first = link.closing.compare_exchange_strong(open, status);
        if (!is_first) { return KIOTTY_NET_CODE_BUSY; }
        return pushFrame(lane, link, FrameOpcode::CLOSE, payload.value.span());
    }

    bool isOpenSocket(const SocketLink& link, int64_t socket)
    {
        return socket != 0 && link.socket.load() == socket;
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_HANDSHAKE_WEBSOCKET_UPGRADE_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_HANDSHAKE_WEBSOCKET_UPGRADE_H

namespace kiotty::net::implementation
{
    class WebSocketHandler;

    UpgradeAnswer            answerUpgrade(WebSocketHandler& handler,
                                           const UpgradeSession& upgrade,
                                           const WebSocketTarget& target);
    KiottyNetWebSocketHandle socketHandleOf(const WebSocketHandler& handler,
                                            const UpgradeSession& upgrade);
    Span<const char>         headerOf(const KiottyNetHttpRequest& request, Span<const char> name);
    KiottyNetCode            chooseProtocol(WebSocketHandler& handler,
                                            const UpgradeSession& upgrade,
                                            Span<const char> protocol);
    bool                     isUpgradeResponse(const KiottyNetHttpRequest& response,
                                               Span<const char> accept,
                                               Span<const char> offered);
}

#endif

#include <cstring>

namespace kiotty::net::implementation
{
    namespace
    {
        enum class UpgradeCheck : uint8_t
        {
            VALID,
            REQUIRED,
            BAD
        };

        enum class TokenMatch : uint8_t
        {
            EXACT,
            IGNORE_CASE
        };

        constexpr char VERSION[] = "13";

        template <size_t N>
        Span<const char> headerNamed(const KiottyNetHttpRequest& request,
                                     const char (&name)[N])
        {
            return headerOf(request, literalOf(name));
        }

        bool                hasToken(Span<const char> list,
                                     Span<const char> token,
                                     TokenMatch match);
        bool                isSameToken(Span<const char> left,
                                        Span<const char> right,
                                        TokenMatch match);
        UpgradeCheck        checkUpgrade(const KiottyNetHttpRequest& request);
        bool                callUpgrade(WebSocketHandler& handler, const UpgradeSession& upgrade);
        KiottyNetSpan       publicSpanOf(Span<const char> text);
        UpgradeAnswer       refuse(const UpgradeSession& upgrade, int32_t status);
        UpgradeAnswer       refuseVersion(const UpgradeSession& upgrade, int32_t status);
        UpgradeAnswer       acceptUpgrade(WebSocketHandler& handler, const UpgradeSession& upgrade);
    }

    UpgradeAnswer answerUpgrade(WebSocketHandler& handler,
                                const UpgradeSession& upgrade,
                                const WebSocketTarget& target)
    {
        const KiottyNetHttpRequest& request = upgrade.request;
        const bool is_get = request.method == KIOTTY_NET_HTTP_METHOD_GET;
        if (!is_get) { return refuse(upgrade, KIOTTY_NET_HTTP_STATUS_METHOD_NOT_ALLOWED); }
        if (upgrade.has_body) { return refuse(upgrade, KIOTTY_NET_HTTP_STATUS_BAD_REQUEST); }
        const UpgradeCheck check = checkUpgrade(request);
        switch (check)
        {
        case UpgradeCheck::VALID:
            break;
        case UpgradeCheck::REQUIRED:
            return refuseVersion(upgrade, KIOTTY_NET_HTTP_STATUS_UPGRADE_REQUIRED);
        case UpgradeCheck::BAD:
            return refuse(upgrade, KIOTTY_NET_HTTP_STATUS_BAD_REQUEST);
        }
        SocketState& socket = socketOf(handler, upgrade);
        socket.reset();
        socket.target = target;
        const bool is_allowed = callUpgrade(handler, upgrade);
        if (!is_allowed) { return refuse(upgrade, KIOTTY_NET_HTTP_STATUS_FORBIDDEN); }
        return acceptUpgrade(handler, upgrade);
    }

    KiottyNetWebSocketHandle socketHandleOf(const WebSocketHandler& handler,
                                            const UpgradeSession& upgrade)
    {
        return KiottyNetWebSocketHandle{ handler.owner, upgrade.id.value() };
    }

    Span<const char> headerOf(const KiottyNetHttpRequest& request, Span<const char> name)
    {
        for (size_t i = 0; i < request.header_count; ++i)
        {
            const KiottyNetHttpHeader& header = request.headers[i];
            const Span<const char> found{ header.name.data, header.name.length };
            if (equalsIgnoreCase(found, name)) { return spanOf(header.value); }
        }
        return Span<const char>{ nullptr, 0 };
    }

    KiottyNetCode chooseProtocol(WebSocketHandler& handler,
                                 const UpgradeSession& upgrade,
                                 Span<const char> protocol)
    {
        const KiottyNetHttpRequest& request = upgrade.request;
        const Span<const char> offered = headerNamed(request, "Sec-WebSocket-Protocol");
        const bool is_offered = hasToken(offered, protocol, TokenMatch::EXACT);
        if (!is_offered) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        (void)socketOf(handler, upgrade).protocol.assign(protocol);
        return KIOTTY_NET_CODE_SUCCESS;
    }

    bool isUpgradeResponse(const KiottyNetHttpRequest& response,
                           Span<const char> accept,
                           Span<const char> offered)
    {
        const TokenMatch caseless = TokenMatch::IGNORE_CASE;
        const Span<const char> upgrade = headerNamed(response, "Upgrade");
        const Span<const char> connection = headerNamed(response, "Connection");
        const Span<const char> answered = headerNamed(response, "Sec-WebSocket-Accept");
        const Span<const char> protocol = headerNamed(response, "Sec-WebSocket-Protocol");
        const bool is_upgrade = hasToken(upgrade, literalOf("websocket"), caseless);
        const bool is_connection = hasToken(connection, literalOf("upgrade"), caseless);
        const bool is_accepted = isSameToken(answered, accept, TokenMatch::EXACT);
        const bool is_offered = protocol.empty() || hasToken(offered, protocol, TokenMatch::EXACT);
        return is_upgrade && is_connection && is_accepted && is_offered;
    }

    namespace
    {
        KiottyNetSpan publicSpanOf(Span<const char> text)
        {
            return KiottyNetSpan{ text.data, text.length };
        }

        bool hasToken(Span<const char> list, Span<const char> token, TokenMatch match)
        {
            size_t start = 0;
            while (start < list.length)
            {
                const size_t comma = findCharacter(list, ',', start);
                const Span<const char> item{ list.data + start, comma - start };
                if (isSameToken(trimWhitespace(item), token, match)) { return true; }
                start = comma + 1;
            }
            return false;
        }

        bool isSameToken(Span<const char> left, Span<const char> right, TokenMatch match)
        {
            if (left.empty() || left.length != right.length) { return false; }
            if (match == TokenMatch::IGNORE_CASE) { return equalsIgnoreCase(left, right); }
            return std::memcmp(left.data, right.data, left.length) == 0;
        }

        UpgradeCheck checkUpgrade(const KiottyNetHttpRequest& request)
        {
            const TokenMatch caseless = TokenMatch::IGNORE_CASE;
            const Span<const char> upgrade = headerNamed(request, "Upgrade");
            const Span<const char> connection = headerNamed(request, "Connection");
            const Span<const char> version = headerNamed(request, "Sec-WebSocket-Version");
            const Span<const char> key = headerNamed(request, "Sec-WebSocket-Key");
            const bool is_upgrade = hasToken(upgrade, literalOf("websocket"), caseless);
            const bool is_connection = hasToken(connection, literalOf("upgrade"), caseless);
            const bool is_version = isSameToken(version, literalOf(VERSION), TokenMatch::EXACT);
            const bool is_complete = is_upgrade && is_connection && is_version && !key.empty();
            if (!is_complete) { return UpgradeCheck::REQUIRED; }
            if (!isWebSocketKey(key)) { return UpgradeCheck::BAD; }
            return UpgradeCheck::VALID;
        }

        bool callUpgrade(WebSocketHandler& handler, const UpgradeSession& upgrade)
        {
            const WebSocketTarget& target = socketOf(handler, upgrade).target;
            if (target.on_upgrade == nullptr) { return true; }
            const KiottyNetHttpRequest& request = upgrade.request;
            const KiottyNetWebSocketUpgrade offer{
                request.path,
                request.query,
                publicSpanOf(headerNamed(request, "Host")),
                publicSpanOf(headerNamed(request, "Origin")),
                publicSpanOf(headerNamed(request, "Sec-WebSocket-Protocol")),
            };
            const KiottyNetWebSocketHandle socket = socketHandleOf(handler, upgrade);
            const KiottyNetBool allowed = target.on_upgrade(upgrade.app_context, socket, offer);
            return allowed != 0;
        }

        UpgradeAnswer refuse(const UpgradeSession& upgrade, int32_t status)
        {
            upgrade.response.begin();
            (void)upgrade.response.setStatus(status);
            const Span<const char> get = literalOf("GET");
            const bool is_not_allowed = status == KIOTTY_NET_HTTP_STATUS_METHOD_NOT_ALLOWED;
            if (is_not_allowed) { (void)upgrade.response.addHeader(literalOf("Allow"), get); }
            return UpgradeAnswer::REFUSE;
        }

        UpgradeAnswer refuseVersion(const UpgradeSession& upgrade, int32_t status)
        {
            upgrade.response.begin();
            (void)upgrade.response.setStatus(status);
            (void)upgrade.response.addHeader(literalOf("Upgrade"), literalOf("websocket"));
            const Span<const char> version = literalOf(VERSION);
            (void)upgrade.response.addHeader(literalOf("Sec-WebSocket-Version"), version);
            return UpgradeAnswer::REFUSE;
        }

        UpgradeAnswer acceptUpgrade(WebSocketHandler& handler, const UpgradeSession& upgrade)
        {
            const KiottyNetHttpRequest& request = upgrade.request;
            const AcceptText accept = acceptOf(headerNamed(request, "Sec-WebSocket-Key"));
            upgrade.response.begin();
            (void)upgrade.response.setStatus(KIOTTY_NET_HTTP_STATUS_SWITCHING_PROTOCOLS);
            (void)upgrade.response.addHeader(literalOf("Upgrade"), literalOf("websocket"));
            (void)upgrade.response.addHeader(literalOf("Sec-WebSocket-Accept"), accept.span());
            const Span<const char> protocol = socketOf(handler, upgrade).protocol.span();
            const Span<const char> protocol_name = literalOf("Sec-WebSocket-Protocol");
            if (!protocol.empty()) { (void)upgrade.response.addHeader(protocol_name, protocol); }
            return UpgradeAnswer::ACCEPT;
        }
    }
}

