namespace kiotty::net::implementation
{
    namespace
    {
        using Next = KiottyNet_Transition<HttpState>;
        using Status = KiottyNetWebSocketStatus;

        constexpr Status FRAME_TOO_BIG = KIOTTY_NET_WEB_SOCKET_STATUS_MESSAGE_TOO_BIG;

        KiottyNetTransition readFrameBytes(WebSocketHandler& handler, const UpgradeSession& upgrade,
                                           WebSocketState state,
                                           Span<const char> bytes);
        KiottyNetTransition readFrameStart(WebSocketHandler& handler,
                                           const UpgradeSession& upgrade,
                                           Span<const char> bytes);
        KiottyNetTransition readFrameLength(WebSocketHandler& handler,
                                            const UpgradeSession& upgrade,
                                            Span<const char> bytes);
        KiottyNetTransition readFrameMask(WebSocketHandler& handler,
                                          const UpgradeSession& upgrade,
                                          Span<const char> bytes);
        KiottyNetTransition readFramePiece(WebSocketHandler& handler,
                                           const UpgradeSession& upgrade,
                                           Span<const char> bytes);
        KiottyNetTransition afterFrameLength(WebSocketHandler& handler,
                                             const UpgradeSession& upgrade,
                                             uint64_t length);
        KiottyNetTransition beginPayload(WebSocketHandler& handler, const UpgradeSession& upgrade);
        KiottyNetTransition continueFrame(WebSocketHandler& handler, const UpgradeSession& upgrade);
    }

    KiottyNetTransition stepFrame(WebSocketHandler& handler,
                                  const UpgradeSession& upgrade,
                                  KiottyNetConnectionEvent event)
    {
        const WebSocketState state = socketOf(handler, upgrade).read.state;
        if (state == WebSocketState::OPENING) { return closeWith(KIOTTY_NET_CODE_UNHANDLED_EVENT); }
        const KiottyNetConnectionEventType type = event.type;
        const bool is_timeout = type == KIOTTY_NET_CONNECTION_EVENT_TYPE_TIMEOUT;
        if (is_timeout) { return timeoutSocket(handler, upgrade); }
        const bool is_read = type == KIOTTY_NET_CONNECTION_EVENT_TYPE_READ;
        if (!is_read) { return closeWith(KIOTTY_NET_CODE_UNHANDLED_EVENT); }
        const Span<const char> bytes = spanOf(event.data);
        return readFrameBytes(handler, upgrade, state, bytes);
    }

    KiottyNetTransition readNext(WebSocketHandler& handler,
                                 const UpgradeSession& upgrade,
                                 FrameRead read)
    {
        socketOf(handler, upgrade).read = read;
        const uint32_t timeout = readTimeoutOf(handler, upgrade);
        return Next::moveToNextState(HttpState::UPGRADED, thenRead(read.length, timeout));
    }

    KiottyNetTransition nextFrame(WebSocketHandler& handler, const UpgradeSession& upgrade)
    {
        return readNext(handler,
                        upgrade,
                        FrameRead{ FRAME_START_BYTES, WebSocketState::FRAME_START });
    }

    namespace
    {
        KiottyNetTransition readFrameBytes(WebSocketHandler& handler, const UpgradeSession& upgrade,
                                           WebSocketState state,
                                           Span<const char> bytes)
        {
            switch (state)
            {
            case WebSocketState::FRAME_LENGTH:
                return readFrameLength(handler, upgrade, bytes);
            case WebSocketState::FRAME_MASK:
                return readFrameMask(handler, upgrade, bytes);
            case WebSocketState::FRAME_PAYLOAD:
                return readFramePiece(handler, upgrade, bytes);
            case WebSocketState::OPENING:
            case WebSocketState::FRAME_START:
                break;
            }
            return readFrameStart(handler, upgrade, bytes);
        }

        KiottyNetTransition readFrameStart(WebSocketHandler& handler,
                                           const UpgradeSession& upgrade,
                                           Span<const char> bytes)
        {
            const FrameStartResult parsed = parseFrameStart(bytes);
            if (!parsed) { return failSocket(handler, upgrade, parsed.code); }
            const FrameStart& start = parsed.value;
            SocketState& socket = socketOf(handler, upgrade);
            const SocketRole role = handler.role;
            const bool is_valid = isAcceptedStart(start, role, socket.message);
            if (!is_valid) { return failSocket(handler, upgrade, CLOSE_PROTOCOL); }
            socket.frame = frameOf(start);
            const size_t extended = extendedLengthBytesOf(start.length_code);
            const FrameRead length_read{ extended, WebSocketState::FRAME_LENGTH };
            if (extended > 0) { return readNext(handler, upgrade, length_read); }
            return afterFrameLength(handler, upgrade, start.length_code);
        }

        KiottyNetTransition readFrameLength(WebSocketHandler& handler,
                                            const UpgradeSession& upgrade,
                                            Span<const char> bytes)
        {
            const FrameLengthResult length = parseExtendedLength(bytes);
            if (!length) { return failSocket(handler, upgrade, length.code); }
            return afterFrameLength(handler, upgrade, length.value);
        }

        KiottyNetTransition readFrameMask(WebSocketHandler& handler,
                                          const UpgradeSession& upgrade,
                                          Span<const char> bytes)
        {
            socketOf(handler, upgrade).frame.key = parseMaskKey(bytes);
            return beginPayload(handler, upgrade);
        }

        KiottyNetTransition readFramePiece(WebSocketHandler& handler,
                                           const UpgradeSession& upgrade,
                                           Span<const char> bytes)
        {
            const bool is_stored = storePiece(handler, upgrade, bytes);
            if (!is_stored) { return failSocket(handler, upgrade, FRAME_TOO_BIG); }
            SocketState& socket = socketOf(handler, upgrade);
            socket.frame = advanceFrame(socket.frame, bytes.length);
            return continueFrame(handler, upgrade);
        }

        KiottyNetTransition afterFrameLength(WebSocketHandler& handler,
                                             const UpgradeSession& upgrade,
                                             uint64_t length)
        {
            SocketState& socket = socketOf(handler, upgrade);
            SocketFrame& frame = socket.frame;
            frame.remaining = length;
            const uint64_t room = upgrade.message.length - socket.message_length;
            if (isOversized(frame, room)) { return failSocket(handler, upgrade, FRAME_TOO_BIG); }
            const bool is_masked = frame.masking == FrameMasking::MASKED;
            const FrameRead mask_read{ MASK_KEY_BYTES, WebSocketState::FRAME_MASK };
            if (is_masked) { return readNext(handler, upgrade, mask_read); }
            return beginPayload(handler, upgrade);
        }

        KiottyNetTransition beginPayload(WebSocketHandler& handler, const UpgradeSession& upgrade)
        {
            SocketState& socket = socketOf(handler, upgrade);
            if (isControl(socket.frame.opcode)) { socket.control_length = 0; }
            return continueFrame(handler, upgrade);
        }

        KiottyNetTransition continueFrame(WebSocketHandler& handler, const UpgradeSession& upgrade)
        {
            const SocketFrame& frame = socketOf(handler, upgrade).frame;
            const FrameEnd end = frameEndOf(frame);
            const size_t capacity = upgrade.receive_capacity;
            if (end == FrameEnd::CONTROL) { return finishControl(handler, upgrade); }
            if (end == FrameEnd::DATA) { return finishData(handler, upgrade); }
            const FrameRead payload_read = payloadReadOf(frame, capacity);
            return readNext(handler, upgrade, payload_read);
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_MESSAGE_WEBSOCKET_MESSAGE_RULES_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_MESSAGE_WEBSOCKET_MESSAGE_RULES_H

namespace kiotty::net::implementation
{
    bool                      isInOrder(FrameOpcode message, FrameOpcode opcode);
    MessageStep               messageStepOf(const SocketFrame& frame, FrameOpcode message);
    bool                      isBrokenMessage(FrameOpcode opcode, Span<const char> body);
    KiottyNetWebSocketMessage appMessageOf(FrameOpcode opcode, KiottyNetSpan data);
}

#endif

namespace kiotty::net::implementation
{
    bool isAcceptedStart(const FrameStart& start, SocketRole role, FrameOpcode message)
    {
        const bool is_masked = start.masking == FrameMasking::MASKED;
        const bool is_server = role == SocketRole::SERVER;
        return is_masked == is_server && isInOrder(message, start.opcode);
    }

    SocketFrame frameOf(const FrameStart& start)
    {
        return SocketFrame{ 0, 0, MaskKey{}, start.opcode, start.finality, start.masking };
    }

    bool isOversized(const SocketFrame& frame, uint64_t room)
    {
        return !isControl(frame.opcode) && frame.remaining > room;
    }

    FrameEnd frameEndOf(const SocketFrame& frame)
    {
        if (frame.remaining > 0) { return FrameEnd::PAYLOAD; }
        if (isControl(frame.opcode)) { return FrameEnd::CONTROL; }
        return FrameEnd::DATA;
    }

    FrameRead payloadReadOf(const SocketFrame& frame, size_t capacity)
    {
        const uint64_t remaining = frame.remaining;
        const uint64_t step = remaining < capacity ? remaining : capacity;
        return FrameRead{ static_cast<size_t>(step), WebSocketState::FRAME_PAYLOAD };
    }

    SocketFrame advanceFrame(const SocketFrame& frame, size_t piece)
    {
        SocketFrame next = frame;
        next.offset += piece;
        next.remaining -= piece;
        return next;
    }
}

namespace kiotty::net::implementation
{
    bool isInOrder(FrameOpcode message, FrameOpcode opcode)
    {
        if (isControl(opcode)) { return true; }
        const bool is_in_message = message != FrameOpcode::CONTINUATION;
        const bool is_continuation = opcode == FrameOpcode::CONTINUATION;
        return is_in_message == is_continuation;
    }

    MessageStep messageStepOf(const SocketFrame& frame, FrameOpcode message)
    {
        const bool is_first = frame.opcode != FrameOpcode::CONTINUATION;
        const FrameOpcode current = is_first ? frame.opcode : message;
        const FrameOpcode none = FrameOpcode::CONTINUATION;
        if (frame.finality == FrameFinality::MORE) { return MessageStep{ current, none, false }; }
        return MessageStep{ none, current, true };
    }

    bool isBrokenMessage(FrameOpcode opcode, Span<const char> body)
    {
        const bool is_text = opcode == FrameOpcode::TEXT;
        return is_text && !isUtf8(body);
    }

    KiottyNetWebSocketMessage appMessageOf(FrameOpcode opcode, KiottyNetSpan data)
    {
        const bool is_text = opcode == FrameOpcode::TEXT;
        const KiottyNetWebSocketOpcode kind =
            is_text ? KIOTTY_NET_WEB_SOCKET_OPCODE_TEXT : KIOTTY_NET_WEB_SOCKET_OPCODE_BINARY;
        return KiottyNetWebSocketMessage{ kind, data };
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_CONTROL_WEBSOCKET_CONTROL_RULES_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_CONTROL_WEBSOCKET_CONTROL_RULES_H

#include <cstdint>

namespace kiotty::net::implementation
{
    ControlAction controlActionOf(FrameOpcode opcode, bool is_closing);
    TimeoutAction timeoutActionOf(bool is_closing, uint64_t ping_deadline);
}

#endif

namespace kiotty::net::implementation
{
    ControlAction controlActionOf(FrameOpcode opcode, bool is_closing)
    {
        if (opcode == FrameOpcode::CLOSE) { return ControlAction::ANSWER_CLOSE; }
        if (opcode == FrameOpcode::PONG) { return ControlAction::CLEAR_PING; }
        const bool is_ping = opcode == FrameOpcode::PING;
        if (is_ping && !is_closing) { return ControlAction::SEND_PONG; }
        return ControlAction::NOTHING;
    }

    TimeoutAction timeoutActionOf(bool is_closing, uint64_t ping_deadline)
    {
        if (is_closing) { return TimeoutAction::CLOSE; }
        if (ping_deadline != 0) { return TimeoutAction::SEND_CLOSE; }
        return TimeoutAction::SEND_PING;
    }
}

namespace kiotty::net::implementation
{
    namespace
    {
        void callMessage(WebSocketHandler& handler,
                         const UpgradeSession& upgrade,
                         const KiottyNetWebSocketMessage& message);
    }

    KiottyNetTransition finishData(WebSocketHandler& handler, const UpgradeSession& upgrade)
    {
        SocketState& socket = socketOf(handler, upgrade);
        const MessageStep step = messageStepOf(socket.frame, socket.message);
        socket.message = step.message;
        if (!step.is_done) { return nextFrame(handler, upgrade); }
        const Span<const char> body{ upgrade.message.data, socket.message_length };
        const bool is_broken = isBrokenMessage(step.delivered, body);
        if (is_broken) { return failSocket(handler, upgrade, CLOSE_INVALID_PAYLOAD); }
        const KiottyNetSpan data{ body.data, body.length };
        const KiottyNetWebSocketMessage message = appMessageOf(step.delivered, data);
        if (!isClosing(handler, upgrade)) { callMessage(handler, upgrade, message); }
        socket.message_length = 0;
        return nextFrame(handler, upgrade);
    }

    bool storePiece(WebSocketHandler& handler,
                    const UpgradeSession& upgrade,
                    Span<const char> piece)
    {
        SocketState& socket = socketOf(handler, upgrade);
        const SocketFrame& frame = socket.frame;
        if (isControl(frame.opcode))
        {
            storeControl(handler, upgrade, piece);
            return true;
        }
        const size_t used = socket.message_length;
        if (piece.length > upgrade.message.length - used) { return false; }
        const Span<char> target{ upgrade.message.data + used, piece.length };
        (void)target.copyFrom(piece);
        socket.message_length = used + piece.length;
        applyMask(target, frame.key, frame.offset);
        return true;
    }

    namespace
    {
        void callMessage(WebSocketHandler& handler,
                         const UpgradeSession& upgrade,
                         const KiottyNetWebSocketMessage& message)
        {
            if (handler.role == SocketRole::CLIENT)
            {
                handler.client.events.on_message(upgrade.app_context, message);
                return;
            }
            const SocketState& socket = socketOf(handler, upgrade);
            const KiottyNetWebSocketMessageAction on_message = socket.target.on_message;
            on_message(socket.context, socketHandleOf(handler, upgrade), message);
        }
    }
}

namespace kiotty::net::implementation
{
    namespace
    {
        using Next = KiottyNet_Transition<HttpState>;
        using Status = KiottyNetWebSocketStatus;

        constexpr Status TOO_BIG = KIOTTY_NET_WEB_SOCKET_STATUS_MESSAGE_TOO_BIG;

        KiottyNetTransition answerClose(WebSocketHandler& handler, const UpgradeSession& upgrade);
        KiottyNetTransition writeClose(WebSocketHandler& handler, const UpgradeSession& upgrade,
                                       Span<const char> payload,
                                       KiottyNetCode code);
        KiottyNetCode       closeCodeOf(Status status);
        MaskKey             closeMaskOf(WebSocketHandler& handler);
        void                callClose(WebSocketHandler& handler,
                                      const UpgradeSession& upgrade,
                                      const KiottyNetWebSocketClose& close);
    }

    KiottyNetTransition timeoutSocket(WebSocketHandler& handler, const UpgradeSession& upgrade)
    {
        SocketState& socket = socketOf(handler, upgrade);
        const bool is_closing = isClosing(handler, upgrade);
        const TimeoutAction action = timeoutActionOf(is_closing, socket.ping_deadline);
        if (action == TimeoutAction::CLOSE) { return closeWith(KIOTTY_NET_CODE_TIMEOUT); }
        const Span<const char> empty{ nullptr, 0 };
        PushLane& lane = *handler.lane;
        const bool is_pong_late = action == TimeoutAction::SEND_CLOSE;
        if (is_pong_late) { (void)pushClose(lane, linkOf(handler, upgrade), GOING_AWAY, empty); }
        else
        {
            (void)pushFrame(lane, linkOf(handler, upgrade), FrameOpcode::PING, empty);
            const uint32_t pong_timeout = upgrade.limits.websocket_pong_timeout_milliseconds;
            socket.ping_deadline = deadlineAfter(pong_timeout);
        }
        return readNext(handler, upgrade, socket.read);
    }

    void endSocket(WebSocketHandler& handler, const UpgradeSession& upgrade, KiottyNetCode reason)
    {
        SocketState& socket = socketOf(handler, upgrade);
        SocketLink& link = linkOf(handler, upgrade);
        if (!socket.is_open) { return; }
        socket.is_open = false;
        link.socket.store(0);
        const KiottyNetWebSocketClose close = closeOf(handler, upgrade, reason);
        callClose(handler, upgrade, close);
        link.path.store(NO_SOCKET_PATH);
    }

    KiottyNetTransition finishControl(WebSocketHandler& handler, const UpgradeSession& upgrade)
    {
        SocketState& socket = socketOf(handler, upgrade);
        const Span<const char> payload{ socket.control, socket.control_length };
        const bool is_closing = isClosing(handler, upgrade);
        const ControlAction action = controlActionOf(socket.frame.opcode, is_closing);
        if (action == ControlAction::ANSWER_CLOSE) { return answerClose(handler, upgrade); }
        if (action == ControlAction::CLEAR_PING) { socket.ping_deadline = 0; }
        if (action == ControlAction::SEND_PONG)
        {
            PushLane& lane = *handler.lane;
            (void)pushFrame(lane, linkOf(handler, upgrade), FrameOpcode::PONG, payload);
        }
        return nextFrame(handler, upgrade);
    }

    KiottyNetTransition failSocket(WebSocketHandler& handler,
                                   const UpgradeSession& upgrade,
                                   Status failure)
    {
        const uint16_t status = static_cast<uint16_t>(failure);
        const KiottyNetCode code = closeCodeOf(failure);
        uint16_t open = 0;
        const bool is_first = linkOf(handler,
                                     upgrade).closing.compare_exchange_strong(open,
                                     status);
        if (!is_first) { return closeWith(code); }
        const char bytes[STATUS_BYTES] = {
            static_cast<char>(static_cast<uint8_t>(status >> BITS_PER_BYTE)),
            static_cast<char>(static_cast<uint8_t>(status & BYTE_MASK)),
        };
        return writeClose(handler, upgrade, Span<const char>{ bytes, STATUS_BYTES }, code);
    }

    void storeControl(WebSocketHandler& handler,
                      const UpgradeSession& upgrade,
                      Span<const char> piece)
    {
        SocketState& socket = socketOf(handler, upgrade);
        const size_t offset = socket.frame.offset;
        const Span<char> target{ socket.control + offset, piece.length };
        (void)target.copyFrom(piece);
        applyMask(target, socket.frame.key, offset);
        socket.control_length = offset + piece.length;
    }

    namespace
    {
        KiottyNetTransition answerClose(WebSocketHandler& handler, const UpgradeSession& upgrade)
        {
            SocketState& socket = socketOf(handler, upgrade);
            const Span<const char> payload{ socket.control, socket.control_length };
            const ClosePayloadResult parsed = parseClosePayload(payload);
            if (!parsed) { return failSocket(handler, upgrade, parsed.code); }
            socket.has_peer_close = true;
            socket.peer_status = parsed.value.status;
            uint16_t open = 0;
            const uint16_t echoed = parsed.value.status;
            const bool is_first = linkOf(handler,
                                         upgrade).closing.compare_exchange_strong(open,
                                         echoed);
            if (!is_first) { return closeWith(KIOTTY_NET_CODE_SUCCESS); }
            const size_t status_bytes = echoed == NO_STATUS ? 0 : STATUS_BYTES;
            const Span<const char> echo{ payload.data, status_bytes };
            return writeClose(handler, upgrade, echo, KIOTTY_NET_CODE_SUCCESS);
        }

        KiottyNetTransition writeClose(WebSocketHandler& handler, const UpgradeSession& upgrade,
                                       Span<const char> payload,
                                       KiottyNetCode code)
        {
            const MaskKey key = closeMaskOf(handler);
            const bool is_client = handler.role == SocketRole::CLIENT;
            const FrameOpcode close = FrameOpcode::CLOSE;
            const FrameHead head = is_client ? buildMaskedFrameHead(close, payload.length, key)
                                             : buildFrameHead(close, payload.length);
            char* const outgoing_bytes = socketOf(handler, upgrade).outgoing;
            const Span<char> outgoing{ outgoing_bytes, CLOSE_FRAME_BYTES };
            (void)outgoing.copyFrom(headBytesOf(head));
            const Span<char> body{ outgoing_bytes + head.length, payload.length };
            (void)body.copyFrom(payload);
            applyMask(body, key, 0);
            const KiottyNetSpan data{ outgoing_bytes, head.length + payload.length };
            const KiottyNetConnectionAction farewell = thenCloseWith(data, code);
            return Next::moveToNextState(HttpState::CLOSING, farewell);
        }

        KiottyNetCode closeCodeOf(Status status)
        {
            if (status == TOO_BIG) { return KIOTTY_NET_CODE_REQUEST_TOO_LARGE; }
            return KIOTTY_NET_CODE_PROTOCOL_ERROR;
        }

        MaskKey closeMaskOf(WebSocketHandler& handler)
        {
            if (handler.role == SocketRole::SERVER) { return MaskKey{}; }
            return nextMaskKey(handler.mask_state);
        }

        void callClose(WebSocketHandler& handler,
                       const UpgradeSession& upgrade,
                       const KiottyNetWebSocketClose& close)
        {
            const KiottyNetAppContext app_context = upgrade.app_context;
            if (handler.role == SocketRole::CLIENT)
            {
                const ClientEvents& events = handler.client.events;
                const KiottyNetWebSocketClientCloseAction on_close = events.on_close;
                if (on_close != nullptr) { on_close(app_context, close); }
                return;
            }
            const SocketState& socket = socketOf(handler, upgrade);
            const KiottyNetWebSocketCloseAction on_close = socket.target.on_close;
            if (on_close == nullptr) { return; }
            on_close(app_context, socket.context, close);
        }
    }
}

#include <limits>

namespace kiotty::net::implementation
{
    namespace
    {
        uint32_t      closeTimeOf(WebSocketHandler& handler, const UpgradeSession& upgrade);
        uint32_t      timeLeft(uint64_t deadline);
        KiottyNetSpan peerReasonOf(WebSocketHandler& handler, const UpgradeSession& upgrade);
    }

    bool isClosing(WebSocketHandler& handler, const UpgradeSession& upgrade)
    {
        return linkOf(handler, upgrade).closing.load() != 0;
    }

    uint32_t readTimeoutOf(WebSocketHandler& handler, const UpgradeSession& upgrade)
    {
        if (isClosing(handler, upgrade)) { return closeTimeOf(handler, upgrade); }
        const uint64_t ping_deadline = socketOf(handler, upgrade).ping_deadline;
        if (ping_deadline != 0) { return timeLeft(ping_deadline); }
        return upgrade.limits.websocket_ping_interval_milliseconds;
    }

    uint64_t deadlineAfter(uint32_t milliseconds)
    {
        if (milliseconds == 0) { return 0; }
        return monotonicMilliseconds() + milliseconds;
    }

    KiottyNetWebSocketClose closeOf(WebSocketHandler& handler,
                                    const UpgradeSession& upgrade,
                                    KiottyNetCode reason)
    {
        KiottyNetWebSocketClose close{ reason, ABNORMAL, KiottyNetSpan{ nullptr, 0 } };
        const SocketState& socket = socketOf(handler, upgrade);
        if (socket.has_peer_close)
        {
            close.status = socket.peer_status;
            close.reason = peerReasonOf(handler, upgrade);
            return close;
        }
        const bool is_dropped = reason == KIOTTY_NET_CODE_PEER_CLOSED
                                || reason == KIOTTY_NET_CODE_SOCKET_ERROR;
        if (is_dropped) { return close; }
        const uint16_t sent = linkOf(handler, upgrade).closing.load();
        const bool is_owner_close = reason == KIOTTY_NET_CODE_CLOSED || sent == 0;
        close.status = is_owner_close ? GOING_AWAY : sent;
        return close;
    }

    namespace
    {
        uint32_t closeTimeOf(WebSocketHandler& handler, const UpgradeSession& upgrade)
        {
            const uint32_t timeout = upgrade.limits.websocket_close_timeout_milliseconds;
            if (timeout == 0) { return 0; }
            SocketState& socket = socketOf(handler, upgrade);
            if (socket.close_deadline == 0) { socket.close_deadline = deadlineAfter(timeout); }
            return timeLeft(socket.close_deadline);
        }

        uint32_t timeLeft(uint64_t deadline)
        {
            const uint64_t now = monotonicMilliseconds();
            if (now >= deadline) { return EXPIRED_MILLISECONDS; }
            const uint64_t left = deadline - now;
            const uint64_t largest = std::numeric_limits<uint32_t>::max();
            return static_cast<uint32_t>(left < largest ? left : largest);
        }

        KiottyNetSpan peerReasonOf(WebSocketHandler& handler, const UpgradeSession& upgrade)
        {
            const SocketState& socket = socketOf(handler, upgrade);
            const size_t length = socket.control_length;
            const bool has_reason = length > STATUS_BYTES;
            const size_t reason_length = has_reason ? length - STATUS_BYTES : 0;
            return KiottyNetSpan{ socket.control + STATUS_BYTES, reason_length };
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_CLIENT_WEBSOCKET_CLIENT_MACHINE_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_CLIENT_WEBSOCKET_CLIENT_MACHINE_H

namespace kiotty::net::implementation
{
    KiottyNetStatefulAppContext webSocketClientStatefulOf(HttpSessionHost& host);
}

#endif

#ifndef KIOTTY_NET_INTERNAL_HTTP_DATA_REPOSITORY_MACHINE_HTTP_RULE_NAMES_H
#define KIOTTY_NET_INTERNAL_HTTP_DATA_REPOSITORY_MACHINE_HTTP_RULE_NAMES_H

namespace kiotty::net::implementation
{
    inline constexpr HttpState HEADER_LINE = HttpState::HEADER_LINE;
    inline constexpr HttpState CLOSING = HttpState::CLOSING;
    inline constexpr HttpState UPGRADED = HttpState::UPGRADED;

    inline constexpr KiottyNetConnectionEventType CONNECTED =
        KIOTTY_NET_CONNECTION_EVENT_TYPE_CONNECTED;
    inline constexpr KiottyNetConnectionEventType READ = KIOTTY_NET_CONNECTION_EVENT_TYPE_READ;
    inline constexpr KiottyNetConnectionEventType WRITTEN =
        KIOTTY_NET_CONNECTION_EVENT_TYPE_WRITTEN;
    inline constexpr KiottyNetConnectionEventType TIMEOUT =
        KIOTTY_NET_CONNECTION_EVENT_TYPE_TIMEOUT;
    inline constexpr KiottyNetConnectionEventType CLOSED = KIOTTY_NET_CONNECTION_EVENT_TYPE_CLOSED;
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        using Next = KiottyNet_Transition<HttpState>;
        using Event = KiottyNetConnectionEvent;
        using Session = KiottyNetConnectionContext;
        using Handle = KiottyNetConnectionHandle;

        constexpr char   PROTOCOL_HEADER[] = "Sec-WebSocket-Protocol";
        constexpr size_t PROTOCOL_HEADER_LENGTH = sizeof(PROTOCOL_HEADER) - 1;

        KiottyNetTransition onClientConnected(Session context, Handle connection, Event event);
        KiottyNetTransition onUpgradeSent(Session context, Handle connection, Event event);
        KiottyNetTransition onStatusLine(Session context, Handle connection, Event event);
        KiottyNetTransition onResponseHeader(Session context, Handle connection, Event event);
        KiottyNetTransition onClientFrame(Session context, Handle connection, Event event);
        KiottyNetTransition onClientTimeout(Session context, Handle connection, Event event);
        KiottyNetTransition onClientClosed(Session context, Handle connection, Event event);

        KiottyNetTransition        writeRequest(HttpSession& session);
        KiottyNetTransition        openClientSocket(HttpSession& session);
        bool                       isSwitchingLine(Span<const char> line);
        KiottyNetConnectionContext createClientSession(KiottyNetAppContext app_context,
                                                       KiottyNetConnectionInfo info);
        void                       releaseClientSession(KiottyNetAppContext app_context,
                                                        KiottyNetConnectionContext context);
        void                       reportClientError(KiottyNetAppContext app_context,
                                                     KiottyNetConnectionInfo info,
                                                     KiottyNetCode code,
                                                     const char* message);

        constexpr HttpState UPGRADE_SENDING = HttpState::SENDING;
        constexpr HttpState STATUS_LINE = HttpState::REQUEST_LINE;

        constexpr auto CLIENT_RULES = KiottyNet_rules(
            KiottyNet_when(CONNECTED).then(onClientConnected).to(UPGRADE_SENDING),
            KiottyNet_from(UPGRADE_SENDING)
                .when(WRITTEN)
                .then(onUpgradeSent)
                .to(UPGRADE_SENDING, STATUS_LINE),
            KiottyNet_from(STATUS_LINE).when(READ).then(onStatusLine).to(HEADER_LINE, CLOSING),
            KiottyNet_from(HEADER_LINE)
                .when(READ)
                .then(onResponseHeader)
                .to(HEADER_LINE, UPGRADED, CLOSING),
            KiottyNet_from(UPGRADED).when(READ).then(onClientFrame).to(UPGRADED, CLOSING),
            KiottyNet_from(UPGRADED).when(TIMEOUT).then(onClientFrame).to(UPGRADED, CLOSING),
            KiottyNet_when(TIMEOUT).then(onClientTimeout).to(CLOSING),
            KiottyNet_when(CLOSED).then(onClientClosed));

        constexpr KiottyNetStateMachine CLIENT_MACHINE =
            KiottyNet_makeStateMachine(CLIENT_RULES, UPGRADE_SENDING);
    }

    KiottyNetStatefulAppContext webSocketClientStatefulOf(HttpSessionHost& host)
    {
        return KiottyNetStatefulAppContext{
            &host, &CLIENT_MACHINE, createClientSession, releaseClientSession, reportClientError,
        };
    }

    namespace
    {
        KiottyNetTransition onClientConnected(Session context, Handle connection, Event)
        {
            HttpSession& session = sessionOf(context);
            advanceSession(session);
            session.request.begin(connection);
            session.response.begin();
            socketOf(session).reset();
            session.state.sent = 0;
            startHeaderClock(session);
            return writeRequest(session);
        }

        KiottyNetTransition onUpgradeSent(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            session.state.sent += event.length;
            const bool has_more = session.state.sent < handlerOf(session).client.request.length;
            if (has_more) { return writeRequest(session); }
            return readLine(session, STATUS_LINE, headerTimeLeft(session));
        }

        KiottyNetTransition onStatusLine(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            const bool is_switching = isSwitchingLine(lineOf(event.data));
            if (!is_switching) { return closeWith(KIOTTY_NET_CODE_PROTOCOL_ERROR); }
            return readLine(session, HEADER_LINE, headerTimeLeft(session));
        }

        KiottyNetTransition onResponseHeader(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            const Span<const char> line = lineOf(event.data);
            const KiottyNetCode broken = KIOTTY_NET_CODE_PROTOCOL_ERROR;
            if (line.empty())
            {
                const KiottyNetHttpRequest& response = session.request.request();
                const ClientUpgrade& upgrade = handlerOf(session).client;
                const bool is_upgraded =
                    isUpgradeResponse(response, upgrade.accept, upgrade.protocols);
                if (!is_upgraded) { return closeWith(broken); }
                const Span<const char> name{ PROTOCOL_HEADER, PROTOCOL_HEADER_LENGTH };
                const Span<const char> chosen = headerOf(response, name);
                (void)socketOf(session).protocol.assign(chosen);
                return openClientSocket(session);
            }
            const KiottyNetHttpStatus status = session.request.takeHeader(line);
            if (status != NO_ERROR_STATUS) { return closeWith(broken); }
            return readLine(session, HEADER_LINE, headerTimeLeft(session));
        }

        KiottyNetTransition onClientFrame(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            return stepFrame(handlerOf(session), upgradeSessionOf(session), event);
        }

        KiottyNetTransition onClientTimeout(Session, Handle, Event)
        {
            return closeWith(KIOTTY_NET_CODE_TIMEOUT);
        }

        KiottyNetTransition onClientClosed(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            ClientUpgrade& upgrade = handlerOf(session).client;
            if (!socketOf(session).is_open) { upgrade.failure = event.reason; }
            endSocket(handlerOf(session), upgradeSessionOf(session), event.reason);
            return Next::moveToNextState(CLOSING, thenHold(0));
        }

        KiottyNetTransition openClientSocket(HttpSession& session)
        {
            const KiottyNetConnectionHandle connection = session.request.request().connection;
            session.request.begin(connection);
            session.state.phase = SessionPhase::SOCKET;
            return openSocket(handlerOf(session), upgradeSessionOf(session));
        }

        KiottyNetTransition writeRequest(HttpSession& session)
        {
            const Span<const char> whole = handlerOf(session).client.request;
            const Span<const char> request = whole.skip(session.state.sent);
            const KiottyNetSpan data{ request.data, request.length };
            const uint32_t timeout = session.host.limits.header_timeout_milliseconds;
            return Next::moveToNextState(UPGRADE_SENDING, thenWrite(data, timeout));
        }

        bool isSwitchingLine(Span<const char> line)
        {
            const StatusLineResult parsed = parseStatusLine(line);
            if (!parsed) { return false; }
            const bool is_one_one = parsed.value.version == HttpVersion::V11;
            return is_one_one && parsed.value.status == KIOTTY_NET_HTTP_STATUS_SWITCHING_PROTOCOLS;
        }

        KiottyNetConnectionContext createClientSession(KiottyNetAppContext app_context,
                                                       KiottyNetConnectionInfo info)
        {
            HttpSessionHost& host = *static_cast<HttpSessionHost*>(app_context);
            handlerOf(host).client.peer = info;
            const SessionResult acquired = host.sessions.acquire(info);
            if (!acquired) { return nullptr; }
            return &acquired.value();
        }

        void releaseClientSession(KiottyNetAppContext app_context,
                                  KiottyNetConnectionContext context)
        {
            HttpSessionHost& host = *static_cast<HttpSessionHost*>(app_context);
            host.sessions.release(sessionOf(context));
        }

        void reportClientError(KiottyNetAppContext app_context,
                               KiottyNetConnectionInfo info,
                               KiottyNetCode code,
                               const char* message)
        {
            HttpSessionHost& host = *static_cast<HttpSessionHost*>(app_context);
            ClientUpgrade& upgrade = handlerOf(host).client;
            const bool is_settled = upgrade.has_opened || upgrade.has_failed;
            if (is_settled) { return; }
            upgrade.has_failed = true;
            host.notices.reportError(host.app_context, info, code, message);
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_SERVER_WEBSOCKET_ACCESS_H
#define KIOTTY_NET_INTERNAL_WEBSOCKET_DATA_REPOSITORY_SERVER_WEBSOCKET_ACCESS_H

#include <cstdint>

namespace kiotty::net::implementation
{
    class WebSocketAccess
    {
    public:
        explicit WebSocketAccess(HttpSessionHost& host);

        KiottyNetWebSocketInfo info(int64_t id);
        KiottyNetSpan          header(int64_t id, Span<const char> name);
        KiottyNetCode          select(int64_t id, Span<const char> protocol);
        KiottyNetCode          send(int64_t id,
                                    KiottyNetWebSocketOpcode opcode,
                                    KiottyNetSpan data);
        KiottyNetCode          close(int64_t id, uint16_t status, Span<const char> reason);
        KiottyNetCode          broadcast(const char* path,
                                         KiottyNetWebSocketOpcode opcode,
                                         KiottyNetSpan data);

    private:
        using LinkResult = Result<SocketLink&, KiottyNetCode>;

        SessionResult upgrading(int64_t id);
        LinkResult    openLink(int64_t id);

        HttpSessionHost&  _host;
        WebSocketHandler& _handler;
    };
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr size_t MAX_SOCKET_PATH_LENGTH = KIOTTY_NET_MAX_URL_LENGTH - 1;

        bool          isDataOpcode(KiottyNetWebSocketOpcode opcode);
        FrameOpcode   frameOpcodeOf(KiottyNetWebSocketOpcode opcode);
        KiottyNetCode checkData(const HttpSessionHost& host,
                                KiottyNetWebSocketOpcode opcode,
                                KiottyNetSpan data);
        bool          isBroadcastTarget(const SocketLink& link, int32_t path);
    }

    WebSocketAccess::WebSocketAccess(HttpSessionHost& host)
        : _host(host)
        , _handler(handlerOf(host))
    {
    }

    KiottyNetWebSocketInfo WebSocketAccess::info(int64_t id)
    {
        KiottyNetWebSocketInfo info{};
        const SessionResult found = _host.sessions.find(id);
        if (!found) { return info; }
        const HttpSession& session = found.value();
        const SocketState& socket = socketOf(session);
        if (!socket.is_open) { return info; }
        info.connection = session.info;
        const Span<char> protocol{ info.protocol, KIOTTY_NET_MAX_WEB_SOCKET_PROTOCOL_LENGTH - 1 };
        (void)protocol.copyFrom(socket.protocol.span());
        return info;
    }

    KiottyNetSpan WebSocketAccess::header(int64_t id, Span<const char> name)
    {
        const SessionResult found = upgrading(id);
        if (!found) { return KiottyNetSpan{ nullptr, 0 }; }
        const Span<const char> value = headerOf(found.value().request.request(), name);
        return KiottyNetSpan{ value.data, value.length };
    }

    KiottyNetCode WebSocketAccess::select(int64_t id, Span<const char> protocol)
    {
        const SessionResult found = upgrading(id);
        if (!found) { return found.code; }
        return chooseProtocol(_handler, upgradeSessionOf(found.value()), protocol);
    }

    KiottyNetCode WebSocketAccess::send(int64_t id,
                                        KiottyNetWebSocketOpcode opcode,
                                        KiottyNetSpan data)
    {
        const KiottyNetCode checked = checkData(_host, opcode, data);
        if (checked != KIOTTY_NET_CODE_SUCCESS) { return checked; }
        const LinkResult link = openLink(id);
        if (!link) { return link.code; }
        if (link.value().closing.load() != 0) { return KIOTTY_NET_CODE_CLOSED; }
        const Span<const char> payload{ data.data, data.length };
        return pushFrame(*_handler.lane, link.value(), frameOpcodeOf(opcode), payload);
    }

    KiottyNetCode WebSocketAccess::close(int64_t id, uint16_t status, Span<const char> reason)
    {
        const LinkResult link = openLink(id);
        if (!link) { return link.code; }
        return pushClose(*_handler.lane, link.value(), status, reason);
    }

    KiottyNetCode WebSocketAccess::broadcast(const char* path,
                                             KiottyNetWebSocketOpcode opcode,
                                             KiottyNetSpan data)
    {
        const KiottyNetCode checked = checkData(_host, opcode, data);
        if (checked != KIOTTY_NET_CODE_SUCCESS) { return checked; }
        int32_t index = NO_SOCKET_PATH;
        if (path != nullptr)
        {
            const TextResult text = parseText(path, MAX_SOCKET_PATH_LENGTH);
            if (!text) { return text.code; }
            index = _host.registry.find(text.value);
            if (index == NO_UPGRADE_ROUTE) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        }
        KiottyNetCode result = KIOTTY_NET_CODE_SUCCESS;
        const Span<const char> payload{ data.data, data.length };
        const FrameOpcode frame = frameOpcodeOf(opcode);
        for (SocketLink& link : _handler.links())
        {
            if (!isBroadcastTarget(link, index)) { continue; }
            const KiottyNetCode pushed = pushFrame(*_handler.lane, link, frame, payload);
            if (pushed == KIOTTY_NET_CODE_BUFFER_FULL) { result = pushed; }
        }
        return result;
    }

    SessionResult WebSocketAccess::upgrading(int64_t id)
    {
        const SessionResult found = _host.sessions.find(id);
        if (!found) { return found; }
        const bool is_upgrading = found.value().state.phase == SessionPhase::UPGRADING;
        if (!is_upgrading) { return SessionResult::failure(KIOTTY_NET_CODE_BUSY); }
        return found;
    }

    WebSocketAccess::LinkResult WebSocketAccess::openLink(int64_t id)
    {
        const PoolHandle handle = PoolHandle::fromValue(id);
        const Span<SocketLink> links = _handler.links();
        const size_t index = static_cast<size_t>(handle.index);
        const bool is_inside = handle.index >= 0 && index < links.length;
        if (!is_inside) { return LinkResult::failure(KIOTTY_NET_CODE_PEER_CLOSED); }
        SocketLink& link = links[index];
        if (!isOpenSocket(link, id)) { return LinkResult::failure(KIOTTY_NET_CODE_PEER_CLOSED); }
        return LinkResult::success(link);
    }

    namespace
    {
        bool isDataOpcode(KiottyNetWebSocketOpcode opcode)
        {
            return opcode == KIOTTY_NET_WEB_SOCKET_OPCODE_TEXT
                   || opcode == KIOTTY_NET_WEB_SOCKET_OPCODE_BINARY;
        }

        FrameOpcode frameOpcodeOf(KiottyNetWebSocketOpcode opcode)
        {
            const bool is_text = opcode == KIOTTY_NET_WEB_SOCKET_OPCODE_TEXT;
            return is_text ? FrameOpcode::TEXT : FrameOpcode::BINARY;
        }

        KiottyNetCode checkData(const HttpSessionHost& host,
                                KiottyNetWebSocketOpcode opcode,
                                KiottyNetSpan data)
        {
            const bool is_empty = data.data == nullptr || data.length == 0;
            if (is_empty || !isDataOpcode(opcode)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
            const bool is_masked = handlerOf(host).role == SocketRole::CLIENT;
            const size_t mask_bytes = is_masked ? MASK_KEY_BYTES : 0;
            const size_t frame_head = buildFrameHead(FrameOpcode::BINARY, data.length).length;
            const size_t head = frame_head + mask_bytes;
            const size_t room = host.push_capacity;
            const bool fits = head <= room && data.length <= room - head;
            if (!fits) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
            return KIOTTY_NET_CODE_SUCCESS;
        }

        bool isBroadcastTarget(const SocketLink& link, int32_t path)
        {
            const bool is_open = link.socket.load() != 0 && link.closing.load() == 0;
            if (!is_open) { return false; }
            return path == NO_SOCKET_PATH || link.path.load() == path;
        }
    }
}

namespace kiotty::net::implementation
{
    SocketLink::SocketLink()
        : socket(0)
        , connection(0)
        , path(NO_SOCKET_PATH)
        , closing(0)
    {
    }

    SocketState::SocketState()
        : target{}
        , context(nullptr)
        , protocol()
        , frame{}
        , read{ 0, WebSocketState::OPENING }
        , ping_deadline(0)
        , close_deadline(0)
        , control_length(0)
        , message_length(0)
        , peer_status(0)
        , message(FrameOpcode::CONTINUATION)
        , control{}
        , outgoing{}
        , is_open(false)
        , has_peer_close(false)
    {
    }

    void SocketState::reset()
    {
        target = WebSocketTarget{ nullptr, nullptr, nullptr, nullptr, NO_SOCKET_PATH };
        context = nullptr;
        protocol.clear();
        frame = SocketFrame{};
        read = FrameRead{ 0, WebSocketState::OPENING };
        ping_deadline = 0;
        close_deadline = 0;
        control_length = 0;
        message_length = 0;
        peer_status = 0;
        message = FrameOpcode::CONTINUATION;
        is_open = false;
        has_peer_close = false;
    }
}

namespace kiotty::net::implementation
{
    SocketTable::SocketTable()
        : _sockets()
        , _links()
        , _count(0)
    {
    }

    void SocketTable::initialize(size_t count)
    {
        if (_sockets.size() < count) { _sockets = std::vector<SocketState>(count); }
        if (_links.size() < count) { _links = std::vector<SocketLink>(count); }
        for (SocketState& socket : _sockets)
        {
            socket.reset();
        }
        _count = count;
    }

    SocketState& SocketTable::socketAt(int32_t index)
    {
        return _sockets[static_cast<size_t>(index)];
    }

    SocketLink& SocketTable::linkAt(int32_t index)
    {
        return _links[static_cast<size_t>(index)];
    }

    Span<SocketLink> SocketTable::links()
    {
        return Span<SocketLink>{ _links.data(), _count };
    }
}

#ifndef KIOTTY_NET_INTERNAL_HTTP_DATA_REPOSITORY_MACHINE_HTTP_MACHINE_H
#define KIOTTY_NET_INTERNAL_HTTP_DATA_REPOSITORY_MACHINE_HTTP_MACHINE_H

namespace kiotty::net::implementation
{
    KiottyNetStatefulAppContext httpStatefulOf(HttpSessionHost& host);
}

#endif

namespace kiotty::net::implementation
{
    namespace
    {
        using Next = KiottyNet_Transition<HttpState>;
        using Event = KiottyNetConnectionEvent;
        using Session = KiottyNetConnectionContext;
        using Handle = KiottyNetConnectionHandle;
        using EventType = KiottyNetConnectionEventType;

        constexpr size_t CHUNK_END_BYTES = 2;
        constexpr char          CONTINUE_LINE[] = "HTTP/1.1 100 Continue\r\n\r\n";
        constexpr KiottyNetSpan CONTINUE_SPAN{ CONTINUE_LINE, sizeof(CONTINUE_LINE) - 1 };

        KiottyNetTransition onConnected(Session context, Handle connection, Event event);
        KiottyNetTransition onRequestLine(Session context, Handle connection, Event event);
        KiottyNetTransition onHeaderLine(Session context, Handle connection, Event event);
        KiottyNetTransition onBody(Session context, Handle connection, Event event);
        KiottyNetTransition onChunkSize(Session context, Handle connection, Event event);
        KiottyNetTransition onChunkData(Session context, Handle connection, Event event);
        KiottyNetTransition onChunkEnd(Session context, Handle connection, Event event);
        KiottyNetTransition onTrailer(Session context, Handle connection, Event event);
        KiottyNetTransition onContinued(Session context, Handle connection, Event event);
        KiottyNetTransition onWorkStarted(Session context, Handle connection, Event event);
        KiottyNetTransition onSent(Session context, Handle connection, Event event);
        KiottyNetTransition onUpgraded(Session context, Handle connection, Event event);
        KiottyNetTransition onTimeout(Session context, Handle connection, Event event);
        KiottyNetTransition onClosed(Session context, Handle connection, Event event);

        KiottyNetTransition afterHeaders(HttpSession& session);
        KiottyNetTransition afterLength(HttpSession& session, uint64_t length);
        KiottyNetTransition beginBody(HttpSession& session);
        KiottyNetTransition readFirstBody(HttpSession& session);
        KiottyNetTransition takeBody(HttpSession& session, KiottyNetSpan data, HttpState more);
        uint32_t            bodyTimeOf(const HttpSession& session);

        KiottyNetConnectionContext createSession(KiottyNetAppContext app_context,
                                                 KiottyNetConnectionInfo info);
        void                       releaseSession(KiottyNetAppContext app_context,
                                                  KiottyNetConnectionContext context);
        void                       reportError(KiottyNetAppContext app_context,
                                               KiottyNetConnectionInfo info,
                                               KiottyNetCode code,
                                               const char* message);

        constexpr HttpState REQUEST_LINE = HttpState::REQUEST_LINE;
        constexpr HttpState BODY = HttpState::BODY;
        constexpr HttpState CHUNK_SIZE = HttpState::CHUNK_SIZE;
        constexpr HttpState CHUNK_DATA = HttpState::CHUNK_DATA;
        constexpr HttpState CHUNK_END = HttpState::CHUNK_END;
        constexpr HttpState TRAILER = HttpState::TRAILER;
        constexpr HttpState CONTINUING = HttpState::CONTINUING;
        constexpr HttpState WORKING = HttpState::WORKING;
        constexpr HttpState SENDING = HttpState::SENDING;

        constexpr EventType WORK_STARTED = KIOTTY_NET_CONNECTION_EVENT_TYPE_WORK_STARTED;

        constexpr auto HTTP_RULES = KiottyNet_rules(
            KiottyNet_when(CONNECTED).then(onConnected).to(REQUEST_LINE),
            KiottyNet_from(REQUEST_LINE)
                .when(READ)
                .then(onRequestLine)
                .to(HEADER_LINE, SENDING, CLOSING),
            KiottyNet_from(HEADER_LINE)
                .when(READ)
                .then(onHeaderLine)
                .to(HEADER_LINE,
                    BODY,
                    CHUNK_SIZE,
                    CONTINUING,
                    SENDING,
                    WORKING,
                    UPGRADED,
                    CLOSING),
            KiottyNet_from(BODY).when(READ).then(onBody).to(BODY, SENDING, WORKING, CLOSING),
            KiottyNet_from(CHUNK_SIZE)
                .when(READ)
                .then(onChunkSize)
                .to(CHUNK_DATA, TRAILER, SENDING, CLOSING),
            KiottyNet_from(CHUNK_DATA)
                .when(READ)
                .then(onChunkData)
                .to(CHUNK_DATA, CHUNK_END, SENDING, CLOSING),
            KiottyNet_from(CHUNK_END).when(READ).then(onChunkEnd).to(CHUNK_SIZE, SENDING, CLOSING),
            KiottyNet_from(TRAILER)
                .when(READ)
                .then(onTrailer)
                .to(TRAILER, SENDING, WORKING, CLOSING),
            KiottyNet_from(CONTINUING).when(WRITTEN).then(onContinued).to(BODY, CHUNK_SIZE),
            KiottyNet_from(WORKING).when(WORK_STARTED).then(onWorkStarted).to(WORKING),
            KiottyNet_from(WORKING).when(WRITTEN).then(onSent).to(SENDING, REQUEST_LINE, CLOSING),
            KiottyNet_from(WORKING)
                .when(READ)
                .then(onRequestLine)
                .to(HEADER_LINE, SENDING, CLOSING),
            KiottyNet_from(SENDING).when(WRITTEN).then(onSent).to(SENDING, REQUEST_LINE, CLOSING),
            KiottyNet_from(UPGRADED).when(WRITTEN).then(onUpgraded).to(UPGRADED, CLOSING),
            KiottyNet_from(UPGRADED).when(READ).then(onUpgraded).to(UPGRADED, CLOSING),
            KiottyNet_from(UPGRADED).when(TIMEOUT).then(onUpgraded).to(UPGRADED, CLOSING),
            KiottyNet_when(TIMEOUT).then(onTimeout).to(CLOSING),
            KiottyNet_when(CLOSED).then(onClosed));

        constexpr KiottyNetStateMachine HTTP_MACHINE =
            KiottyNet_makeStateMachine(HTTP_RULES, REQUEST_LINE);
    }

    KiottyNetStatefulAppContext httpStatefulOf(HttpSessionHost& host)
    {
        return KiottyNetStatefulAppContext{
            &host, &HTTP_MACHINE, createSession, releaseSession, reportError,
        };
    }

    namespace
    {
        KiottyNetTransition onConnected(Session context, Handle connection, Event)
        {
            HttpSession& session = sessionOf(context);
            const uint32_t wait = session.host.limits.header_timeout_milliseconds;
            return beginExchange(session, connection, wait);
        }

        KiottyNetTransition onRequestLine(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            startHeaderClock(session);
            const KiottyNetHttpStatus status = session.request.takeRequestLine(lineOf(event.data));
            if (status != NO_ERROR_STATUS) { return reject(session, status); }
            return readLine(session, HEADER_LINE, headerTimeLeft(session));
        }

        KiottyNetTransition onHeaderLine(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            const Span<const char> line = lineOf(event.data);
            if (line.empty()) { return afterHeaders(session); }
            const KiottyNetHttpStatus status = session.request.takeHeader(line);
            if (status != NO_ERROR_STATUS) { return reject(session, status); }
            return readLine(session, HEADER_LINE, headerTimeLeft(session));
        }

        KiottyNetTransition onBody(Session context, Handle, Event event)
        {
            return takeBody(sessionOf(context), event.data, BODY);
        }

        KiottyNetTransition onChunkSize(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            const LengthResult size = parseChunkSize(lineOf(event.data));
            if (!size) { return reject(session, size.code); }
            if (size.value == 0) { return readLine(session, TRAILER, bodyTimeOf(session)); }
            const uint64_t used = session.request.request().body.length;
            const uint64_t room = session.host.limits.max_body_bytes - used;
            const BodyPlanResult plan = planBody(size.value, room);
            if (!plan) { return reject(session, plan.code); }
            session.state.body = plan.value;
            return readBody(session, CHUNK_DATA);
        }

        KiottyNetTransition onChunkData(Session context, Handle, Event event)
        {
            return takeBody(sessionOf(context), event.data, CHUNK_DATA);
        }

        KiottyNetTransition onChunkEnd(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            const bool has_two_bytes = event.data.length == CHUNK_END_BYTES;
            const bool is_line_end = has_two_bytes && lineOf(event.data).empty();
            if (!is_line_end) { return reject(session, KIOTTY_NET_HTTP_STATUS_BAD_REQUEST); }
            return readLine(session, CHUNK_SIZE, bodyTimeOf(session));
        }

        KiottyNetTransition onTrailer(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            if (lineOf(event.data).empty()) { return dispatch(session); }
            return readLine(session, TRAILER, bodyTimeOf(session));
        }

        KiottyNetTransition onContinued(Session context, Handle, Event)
        {
            return readFirstBody(sessionOf(context));
        }

        KiottyNetTransition onWorkStarted(Session context, Handle, Event event)
        {
            return startWork(sessionOf(context), event.stream);
        }

        KiottyNetTransition onSent(Session context, Handle connection, Event event)
        {
            HttpSession& session = sessionOf(context);
            session.state.sent += event.length;
            return sendNext(session, connection);
        }

        KiottyNetTransition onUpgraded(Session context, Handle, Event event)
        {
            return stepUpgraded(sessionOf(context), event);
        }

        KiottyNetTransition onTimeout(Session, Handle, Event)
        {
            return closeWith(KIOTTY_NET_CODE_TIMEOUT);
        }

        KiottyNetTransition onClosed(Session context, Handle, Event event)
        {
            HttpSession& session = sessionOf(context);
            HttpUpgradeHandler* const upgrade = session.host.upgrade;
            if (upgrade != nullptr) { upgrade->end(upgradeSessionOf(session), event.reason); }
            const KiottyNetAppContext app_context = session.host.app_context;
            session.host.notices.reportDisconnected(app_context, session.info, event.reason);
            return Next::moveToNextState(CLOSING, thenHold(0));
        }

        KiottyNetTransition afterHeaders(HttpSession& session)
        {
            const RequestFramingResult framing = session.request.finishHeaders();
            if (!framing) { return reject(session, framing.code); }
            session.state.framing = framing.value;
            session.state.persistence = framing.value.persistence;
            const BodyFraming& body = framing.value.body;
            switch (body.kind)
            {
            case BodyKind::NONE:
                return dispatch(session);
            case BodyKind::LENGTH:
                return afterLength(session, body.length);
            case BodyKind::CHUNKED:
                return beginBody(session);
            }
            return dispatch(session);
        }

        KiottyNetTransition afterLength(HttpSession& session, uint64_t length)
        {
            const BodyPlanResult plan = planBody(length, session.host.limits.max_body_bytes);
            if (!plan) { return reject(session, plan.code); }
            if (!hasMoreBody(plan.value)) { return dispatch(session); }
            session.state.body = plan.value;
            return beginBody(session);
        }

        KiottyNetTransition beginBody(HttpSession& session)
        {
            if (!session.state.framing.expects_continue) { return readFirstBody(session); }
            return Next::moveToNextState(CONTINUING, thenWrite(CONTINUE_SPAN, 0));
        }

        KiottyNetTransition readFirstBody(HttpSession& session)
        {
            if (hasMoreBody(session.state.body)) { return readBody(session, BODY); }
            return readLine(session, CHUNK_SIZE, bodyTimeOf(session));
        }

        KiottyNetTransition takeBody(HttpSession& session, KiottyNetSpan data, HttpState more)
        {
            const Span<const char> piece{ data.data, data.length };
            const AppendedBodyResult appended = session.request.appendBody(piece);
            if (!appended) { return reject(session, appended.code); }
            session.state.body = takeBodyPiece(session.state.body, data.length);
            if (hasMoreBody(session.state.body)) { return readBody(session, more); }
            const bool is_chunk = more == CHUNK_DATA;
            const uint32_t timeout = bodyTimeOf(session);
            const KiottyNetConnectionAction line_end = thenRead(CHUNK_END_BYTES, timeout);
            if (is_chunk) { return Next::moveToNextState(CHUNK_END, line_end); }
            return dispatch(session);
        }

        uint32_t bodyTimeOf(const HttpSession& session)
        {
            return session.host.limits.header_timeout_milliseconds;
        }

        KiottyNetConnectionContext createSession(KiottyNetAppContext app_context,
                                                 KiottyNetConnectionInfo info)
        {
            HttpSessionHost& host = *static_cast<HttpSessionHost*>(app_context);
            const SessionResult acquired = host.sessions.acquire(info);
            if (!acquired) { return nullptr; }
            return &acquired.value();
        }

        void releaseSession(KiottyNetAppContext app_context, KiottyNetConnectionContext context)
        {
            HttpSessionHost& host = *static_cast<HttpSessionHost*>(app_context);
            host.sessions.release(sessionOf(context));
        }

        void reportError(KiottyNetAppContext app_context,
                         KiottyNetConnectionInfo info,
                         KiottyNetCode code,
                         const char* message)
        {
            const HttpSessionHost& host = *static_cast<HttpSessionHost*>(app_context);
            host.notices.reportError(host.app_context, info, code, message);
        }
    }
}

#ifndef KIOTTY_NET_INTERNAL_BASE_DATA_INFRA_CLOCK_WALL_CLOCK_H
#define KIOTTY_NET_INTERNAL_BASE_DATA_INFRA_CLOCK_WALL_CLOCK_H

namespace kiotty::net::implementation
{
    CalendarTime currentUtcTime();
}

#endif

#include <ctime>

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr int32_t TM_YEAR_ORIGIN = 1900;
        constexpr int32_t TM_MONTH_ORIGIN = 1;

        std::tm splitUtc(std::time_t now);
    }

    CalendarTime currentUtcTime()
    {
        const std::time_t now = std::time(nullptr);
        const std::tm parts = splitUtc(now);
        return CalendarTime{ parts.tm_year + TM_YEAR_ORIGIN,
                             parts.tm_mon + TM_MONTH_ORIGIN,
                             parts.tm_mday,
                             parts.tm_wday,
                             parts.tm_hour,
                             parts.tm_min,
                             parts.tm_sec };
    }

    namespace
    {
        std::tm splitUtc(std::time_t now)
        {
            std::tm parts{};
#if defined(_WIN32)
            (void)gmtime_s(&parts, &now);
#else
            (void)gmtime_r(&now, &parts);
#endif
            return parts;
        }
    }
}

namespace kiotty::net::implementation
{
    namespace
    {
    }

    HttpRequestStore::HttpRequestStore(Span<char> header_buffer,
                                       Span<KiottyNetHttpHeader> headers,
                                       Span<char> body_buffer)
        : _request{}
        , _header_buffer(header_buffer)
        , _headers(headers)
        , _body_buffer(body_buffer)
        , _header_length(0)
        , _version(HttpVersion::V11)
    {
    }

    void HttpRequestStore::begin(KiottyNetConnectionHandle connection)
    {
        _request = KiottyNetHttpRequest{};
        _request.connection = connection;
        _request.headers = _headers.data;
        _request.body = KiottyNetSpan{ _body_buffer.data, 0 };
        _header_length = 0;
        _version = HttpVersion::V11;
    }

    KiottyNetHttpStatus HttpRequestStore::takeRequestLine(Span<const char> line)
    {
        const Span<char> copied = claimHeaderRoom(line);
        if (copied.length != line.length) { return TOO_LARGE; }
        const Span<const char> text{ copied.data, copied.length };
        const RequestLineResult parsed = parseRequestLine(text);
        if (!parsed) { return parsed.code; }
        _request.method = parsed.value.method;
        _request.path = spanOf(parsed.value.path);
        _request.query = spanOf(parsed.value.query);
        _version = parsed.value.version;
        return NO_ERROR_STATUS;
    }

    KiottyNetHttpStatus HttpRequestStore::takeHeader(Span<const char> line)
    {
        const bool is_full = _request.header_count >= _headers.length;
        if (is_full) { return TOO_LARGE; }
        const size_t room = _header_buffer.length - _header_length;
        const Span<char> copied = claimHeaderRoom(line);
        if (copied.length != line.length) { return TOO_LARGE; }
        const Span<const char> text{ copied.data, copied.length };
        const HeaderResult parsed = parseHeaderLine(text, room);
        if (!parsed) { return parsed.code; }
        _headers[_request.header_count] = parsed.value;
        _request.header_count += 1;
        return NO_ERROR_STATUS;
    }

    RequestFramingResult HttpRequestStore::finishHeaders()
    {
        const Span<const KiottyNetHttpHeader> found{ _headers.data, _request.header_count };
        const Persistence persistence = decidePersistence(_version, found);
        _request.keep_alive = persistence == Persistence::KEEP_ALIVE ? 1 : 0;
        const FramingResult body = selectBodyFraming(found);
        if (!body) { return RequestFramingResult::failure(body.code); }
        const bool is_continuing = expectsContinue(_version, found);
        const RequestFraming framing{ body.value, persistence, is_continuing };
        return RequestFramingResult::success(framing);
    }

    AppendedBodyResult HttpRequestStore::appendBody(Span<const char> data)
    {
        const size_t used = _request.body.length;
        const size_t room = _body_buffer.length - used;
        if (data.length > room) { return AppendedBodyResult::failure(CONTENT_TOO_LARGE); }
        const Span<char> target{ _body_buffer.data + used, data.length };
        (void)target.copyFrom(data);
        _request.body.length = used + data.length;
        return AppendedBodyResult::success(target);
    }

    const KiottyNetHttpRequest& HttpRequestStore::request() const
    {
        return _request;
    }

    Span<char> HttpRequestStore::bodyArea() const
    {
        return _body_buffer;
    }

    Span<char> HttpRequestStore::claimHeaderRoom(Span<const char> line)
    {
        const size_t room = _header_buffer.length - _header_length;
        if (line.length > room) { return Span<char>{ nullptr, 0 }; }
        const Span<char> target{ _header_buffer.data + _header_length, line.length };
        (void)target.copyFrom(line);
        _header_length += line.length;
        return target;
    }

    namespace
    {
    }
}

#include <algorithm>

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr int32_t STATUS_MIN = 100;
        constexpr int32_t STATUS_MAX = 599;
        constexpr int32_t STATUS_OK = 200;
        constexpr int32_t STATUS_NOT_FOUND = 404;
        constexpr int32_t STATUS_NO_CONTENT = 204;
        constexpr int32_t STATUS_NOT_MODIFIED = 304;
        constexpr size_t  SEPARATOR_BYTES = 2;
        constexpr char    LAST_CHUNK[] = "0\r\n\r\n";

        constexpr const char* RESERVED_RESPONSE_NAMES[] = {
            "Content-Length", "Transfer-Encoding", "Connection", "Date", "Content-Type",
        };

        ResponseLayout   emptyLayout(Span<char> buffer);
        bool             isReservedResponseName(Span<const char> name);
        bool             isFieldText(Span<const char> value);
        bool             isBodiless(int32_t status);
        bool             isNamedBodyType(KiottyNetHttpContentType type, BodyStorage storage);
        void             writeField(Span<char> target,
                                    Span<const char> name,
                                    Span<const char> value);
        void             appendFraming(PrefixText& prefix, const ResponseLayout& layout);
        Span<const char> sealedBodyOf(const ResponseLayout& layout, bool is_bodiless);
        uint64_t         bodyLengthOf(const ResponseLayout& layout);
        size_t           headerLengthOf(const ResponseLayout& layout);
    }

    ResponseFrame::ResponseFrame(const ResponseLayout& layout)
        : _layout(layout)
    {
    }

    Span<const char> ResponseFrame::chunkAt(size_t offset, size_t max_length) const
    {
        const size_t header_length = _layout.header_end - _layout.header_start;
        const bool is_header = offset < header_length;
        const size_t start = is_header ? _layout.header_start + offset : 0;
        const size_t header_rest = is_header ? header_length - offset : 0;
        const Span<const char> header{ _layout.buffer.data + start, header_rest };
        const bool is_file = _layout.storage == BodyStorage::FILE;
        const Span<const char> body{ _layout.body.data, is_file ? 0 : _layout.sendable_body };
        const Span<const char> rest = is_header ? header : body.skip(offset - header_length);
        return Span<const char>{ rest.data, std::min(rest.length, max_length) };
    }

    KiottyNetCode ResponseFrame::checkChunk(Span<const char> data) const
    {
        const bool has_data = data.data != nullptr && data.length > 0;
        if (!isStream() || !has_data) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const bool is_text = textKindOf(_layout.type) != TextKind::BINARY;
        if (is_text && !isUtf8(data)) { return KIOTTY_NET_CODE_INVALID_ENCODING; }
        return KIOTTY_NET_CODE_SUCCESS;
    }

    bool ResponseFrame::isStream() const
    {
        return _layout.has_body && _layout.storage == BodyStorage::STREAM;
    }

    FilePiece ResponseFrame::filePieceAt(size_t offset, size_t max_length) const
    {
        const size_t header_length = headerLengthOf(_layout);
        const bool is_file = _layout.storage == BodyStorage::FILE && offset >= header_length;
        const size_t body_offset = is_file ? offset - header_length : 0;
        const bool has_rest = is_file && body_offset < _layout.sendable_body;
        const FilePiece none{ Span<char>{ nullptr, 0 }, 0, false };
        if (!has_rest) { return none; }
        const size_t rest = _layout.sendable_body - body_offset;
        const size_t length = std::min(std::min(rest, max_length), _layout.buffer.length);
        return FilePiece{ Span<char>{ _layout.buffer.data, length }, body_offset, true };
    }

    bool ResponseFrame::hasSendableBody() const
    {
        return _layout.sendable_body > 0;
    }

    Span<const char> ResponseFrame::frameChunk(Span<const char> data,
                                               size_t kept,
                                               size_t limit) const
    {
        const Span<const char> none{ nullptr, 0 };
        const Span<char> area = _layout.buffer.skip(_layout.header_start);
        const size_t room = std::min(area.length, limit);
        const ChunkHead head = chunkHeadOf(data.length);
        const size_t framing = kept + head.length() + LINE_END_BYTES;
        const bool has_room = framing <= room && data.length <= room - framing;
        if (!has_room) { return none; }
        const Span<char> head_target = area.skip(kept);
        (void)head_target.copyFrom(head.span());
        const Span<char> data_target = head_target.skip(head.length());
        (void)data_target.copyFrom(data);
        const Span<char> tail_target = data_target.skip(data.length);
        (void)tail_target.copyFrom(literalOf("\r\n"));
        return Span<const char>{ area.data, framing + data.length };
    }

    HttpResponseStore::HttpResponseStore(Span<char> buffer)
        : _layout(emptyLayout(buffer))
        , _custom()
        , _status(0)
        , _is_touched(false)
    {
    }

    void HttpResponseStore::begin()
    {
        _layout = emptyLayout(_layout.buffer);
        _custom.clear();
        _status = 0;
        _is_touched = false;
    }

    KiottyNetCode HttpResponseStore::setStatus(int32_t status)
    {
        const bool is_valid = status >= STATUS_MIN && status <= STATUS_MAX;
        if (!is_valid) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        _status = status;
        _is_touched = true;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode HttpResponseStore::addHeader(Span<const char> name, Span<const char> value)
    {
        const bool is_name = isToken(name) && !isReservedResponseName(name);
        if (!is_name) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isFieldText(value)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isUtf8(value)) { return KIOTTY_NET_CODE_INVALID_ENCODING; }
        const size_t needed = name.length + value.length + SEPARATOR_BYTES + LINE_END_BYTES;
        if (needed > headerRoom()) { return KIOTTY_NET_CODE_BUFFER_FULL; }
        const Span<char> target{ _layout.buffer.data + _layout.header_end, needed };
        writeField(target, name, value);
        _layout.header_end += needed;
        _is_touched = true;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode HttpResponseStore::setCustomContentType(const char* content_type)
    {
        const TextResult parsed = parseCustomContentType(content_type);
        if (!parsed) { return parsed.code; }
        (void)_custom.assign(parsed.value);
        _is_touched = true;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode HttpResponseStore::setBody(KiottyNetHttpContentType type,
                                             KiottyNetSpan data,
                                             BodyStorage storage)
    {
        const bool is_inline = storage == BodyStorage::COPY || storage == BodyStorage::REFERENCE;
        const bool is_missing = is_inline && data.data == nullptr && data.length > 0;
        if (is_missing) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const KiottyNetCode checked = checkBodyType(type, storage);
        if (checked != KIOTTY_NET_CODE_SUCCESS) { return checked; }
        const Span<const char> body{ data.data, is_inline ? data.length : 0 };
        const bool is_text = textKindOf(type) != TextKind::BINARY;
        if (is_text && !isUtf8(body)) { return KIOTTY_NET_CODE_INVALID_ENCODING; }
        const bool is_copy = storage == BodyStorage::COPY;
        const size_t room = _layout.buffer.length - _layout.header_end - LINE_END_BYTES;
        if (is_copy && body.length > room) { return KIOTTY_NET_CODE_BUFFER_FULL; }
        const size_t end = _layout.buffer.length;
        _layout.body_start = is_copy ? end - body.length : end;
        const Span<char> target{ _layout.buffer.data + _layout.body_start, body.length };
        if (is_copy) { (void)target.copyFrom(body); }
        _layout.body = is_copy ? Span<const char>{ target.data, target.length } : body;
        _layout.file_length = storage == BodyStorage::FILE ? data.length : 0;
        _layout.type = type;
        _layout.storage = storage;
        _layout.has_body = true;
        _is_touched = true;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    void HttpResponseStore::seal(const ResponseSeal& seal)
    {
        const int32_t status = finalStatus();
        const bool is_bodiless = isBodiless(status);
        const bool is_head = seal.method == KIOTTY_NET_HTTP_METHOD_HEAD;
        _layout.body = sealedBodyOf(_layout, is_bodiless);
        PrefixText prefix;
        (void)appendStatusLine(prefix, status);
        (void)appendDateField(prefix, currentUtcTime());
        if (!is_bodiless) { appendFraming(prefix, _layout); }
        const bool has_type = _layout.has_body && !is_bodiless;
        if (has_type) { (void)appendField(prefix, literalOf("Content-Type"), contentTypeText()); }
        const bool is_closing = seal.persistence == Persistence::CLOSE;
        if (is_closing) { (void)appendField(prefix, literalOf("Connection"), literalOf("close")); }
        const Span<const char> upgrade = literalOf("Upgrade");
        const bool is_upgrade = seal.persistence == Persistence::UPGRADE;
        if (is_upgrade) { (void)appendField(prefix, literalOf("Connection"), upgrade); }
        _layout.header_start = RESPONSE_PREFIX_BYTES - prefix.length();
        const Span<char> head{ _layout.buffer.data + _layout.header_start, prefix.length() };
        (void)head.copyFrom(prefix.span());
        const Span<char> end{ _layout.buffer.data + _layout.header_end, LINE_END_BYTES };
        (void)end.copyFrom(literalOf("\r\n"));
        _layout.header_end += LINE_END_BYTES;
        const uint64_t length = bodyLengthOf(_layout);
        _layout.sendable_body = is_head || is_bodiless ? 0 : static_cast<size_t>(length);
    }

    ResponseFrame HttpResponseStore::frame() const
    {
        return ResponseFrame(_layout);
    }

    KiottyNetCode HttpResponseStore::checkBodyType(KiottyNetHttpContentType type,
                                                   BodyStorage storage) const
    {
        if (isNamedBodyType(type, storage)) { return KIOTTY_NET_CODE_SUCCESS; }
        const bool is_custom = type == KIOTTY_NET_HTTP_CONTENT_TYPE_CUSTOM && !_custom.empty();
        if (is_custom) { return KIOTTY_NET_CODE_SUCCESS; }
        return KIOTTY_NET_CODE_INVALID_ARGUMENT;
    }

    size_t HttpResponseStore::headerRoom() const
    {
        return _layout.body_start - _layout.header_end - LINE_END_BYTES;
    }

    Span<const char> HttpResponseStore::contentTypeText() const
    {
        if (_layout.type == KIOTTY_NET_HTTP_CONTENT_TYPE_CUSTOM) { return _custom.span(); }
        return contentTypeTextOf(_layout.type);
    }

    int32_t HttpResponseStore::finalStatus() const
    {
        if (_status != 0) { return _status; }
        if (_is_touched) { return STATUS_OK; }
        return STATUS_NOT_FOUND;
    }

    namespace
    {
        ResponseLayout emptyLayout(Span<char> buffer)
        {
            return ResponseLayout{
                buffer,
                Span<const char>{ nullptr, 0 },
                0,
                RESPONSE_PREFIX_BYTES,
                RESPONSE_PREFIX_BYTES,
                buffer.length,
                0,
                KIOTTY_NET_HTTP_CONTENT_TYPE_OCTET_STREAM,
                BodyStorage::COPY,
                false,
            };
        }

        bool isReservedResponseName(Span<const char> name)
        {
            for (const char* reserved : RESERVED_RESPONSE_NAMES)
            {
                if (equalsLiteralIgnoreCase(name, reserved)) { return true; }
            }
            return false;
        }

        bool isFieldText(Span<const char> value)
        {
            for (size_t i = 0; i < value.length; ++i)
            {
                const unsigned char byte = static_cast<unsigned char>(value[i]);
                const bool is_control = byte < ' ' && value[i] != '\t';
                const bool is_delete = value[i] == '\x7F';
                if (is_control || is_delete) { return false; }
            }
            return true;
        }

        bool isBodiless(int32_t status)
        {
            const bool is_informational = status < STATUS_OK;
            return is_informational || status == STATUS_NO_CONTENT || status == STATUS_NOT_MODIFIED;
        }

        bool isNamedBodyType(KiottyNetHttpContentType type, BodyStorage storage)
        {
            const bool is_listed = type >= KIOTTY_NET_HTTP_CONTENT_TYPE_OCTET_STREAM
                                   && type < KIOTTY_NET_HTTP_CONTENT_TYPE_BY_EXTENSION;
            const bool is_event_stream = type == KIOTTY_NET_HTTP_CONTENT_TYPE_EVENT_STREAM;
            const bool is_stream = storage == BodyStorage::STREAM;
            return is_listed && (is_stream || !is_event_stream);
        }

        void writeField(Span<char> target, Span<const char> name, Span<const char> value)
        {
            (void)target.copyFrom(name);
            const Span<char> separator = target.skip(name.length);
            (void)separator.copyFrom(literalOf(": "));
            const Span<char> text = separator.skip(SEPARATOR_BYTES);
            (void)text.copyFrom(value);
            const Span<char> end = text.skip(value.length);
            (void)end.copyFrom(literalOf("\r\n"));
        }

        void appendFraming(PrefixText& prefix, const ResponseLayout& layout)
        {
            const bool is_stream = layout.has_body && layout.storage == BodyStorage::STREAM;
            const Span<const char> name = literalOf("Transfer-Encoding");
            if (is_stream) { (void)appendField(prefix, name, literalOf("chunked")); }
            if (!is_stream) { (void)appendLengthField(prefix, bodyLengthOf(layout)); }
        }

        Span<const char> sealedBodyOf(const ResponseLayout& layout, bool is_bodiless)
        {
            const bool is_stream = layout.has_body && layout.storage == BodyStorage::STREAM;
            if (!is_stream) { return layout.body; }
            if (is_bodiless) { return Span<const char>{ nullptr, 0 }; }
            return Span<const char>{ LAST_CHUNK, sizeof(LAST_CHUNK) - 1 };
        }

        uint64_t bodyLengthOf(const ResponseLayout& layout)
        {
            const bool is_file = layout.storage == BodyStorage::FILE;
            return is_file ? layout.file_length : layout.body.length;
        }

        size_t headerLengthOf(const ResponseLayout& layout)
        {
            return layout.header_end - layout.header_start;
        }
    }
}

#include <cstring>

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr uint32_t GET_BIT = KIOTTY_NET_HTTP_METHOD_BIT(KIOTTY_NET_HTTP_METHOD_GET);
        constexpr uint32_t HEAD_BIT = KIOTTY_NET_HTTP_METHOD_BIT(KIOTTY_NET_HTTP_METHOD_HEAD);
        constexpr uint32_t STATIC_METHODS = GET_BIT | HEAD_BIT;
        constexpr uint32_t ALL_METHODS = 0xFFFFFFFFU;
        constexpr size_t   MAX_LOCATION_LENGTH = KIOTTY_NET_MAX_PATH_LENGTH - 2;
        constexpr KiottyNetSpan NO_MEMORY{ nullptr, 0 };

        using TextLocation = Result<Span<const char>, KiottyNetCode>;

        bool         isMethodKnown(KiottyNetHttpMethod method);
        bool         isWholeServer(Span<const char> path);
        bool         isSamePath(const RoutePath& left, const RoutePath& right);
        bool         isSeparator(char character);
        TextLocation parseLocation(const char* text);
        KiottyNetCode checkMemory(KiottyNetHttpContentType type, KiottyNetSpan data);
        RouteMatch   matchOf(MatchKind kind, uint32_t allowed);
        uint32_t     takenMethodsOf(uint32_t methods, int32_t upgrade);
    }

    HttpRegistry::HttpRegistry()
        : _entries()
        , _not_found{}
        , _max_routes(0)
        , _upgrades(0)
    {
    }

    void HttpRegistry::initialize(size_t max_routes)
    {
        _entries.clear();
        _entries.reserve(max_routes);
        _not_found = KiottyNetHttpRoute{};
        _max_routes = max_routes;
        _upgrades = 0;
    }

    KiottyNetCode HttpRegistry::addRoute(KiottyNetHttpMethod method,
                                         const char* path,
                                         KiottyNetHttpRoute route)
    {
        if (!isMethodKnown(method)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (route.onRequest == nullptr) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const RoutePathResult parsed = parseRoutePath(path);
        if (!parsed) { return parsed.code; }
        const uint32_t bit = KIOTTY_NET_HTTP_METHOD_BIT(method);
        const KiottyNetCode admitted = admit(parsed.value, bit);
        if (admitted != KIOTTY_NET_CODE_SUCCESS) { return admitted; }
        RouteEntry entry{};
        (void)entry.path.assign(parsed.value.text);
        entry.route = route;
        entry.methods = bit;
        entry.upgrade = NO_UPGRADE_ROUTE;
        entry.kind = parsed.value.kind;
        entry.source = StaticKind::NONE;
        _entries.push_back(entry);
        return KIOTTY_NET_CODE_SUCCESS;
    }

    UpgradeIndexResult HttpRegistry::addRoute(const char* path)
    {
        const RoutePathResult parsed = parseRoutePath(path);
        if (!parsed) { return UpgradeIndexResult::failure(parsed.code); }
        const KiottyNetCode admitted = admit(parsed.value, ALL_METHODS);
        if (admitted != KIOTTY_NET_CODE_SUCCESS) { return UpgradeIndexResult::failure(admitted); }
        const int32_t index = _upgrades;
        _upgrades += 1;
        RouteEntry entry{};
        (void)entry.path.assign(parsed.value.text);
        entry.methods = GET_BIT;
        entry.upgrade = index;
        entry.kind = parsed.value.kind;
        entry.source = StaticKind::NONE;
        _entries.push_back(entry);
        return UpgradeIndexResult::success(index);
    }

    KiottyNetCode HttpRegistry::setNotFound(KiottyNetHttpRoute route)
    {
        if (route.onRequest == nullptr) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        _not_found = route;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode HttpRegistry::addDirectory(const char* url_prefix, const char* directory)
    {
        const RoutePathResult parsed = parseDirectoryPrefix(url_prefix);
        if (!parsed) { return parsed.code; }
        const TextLocation location = parseLocation(directory);
        if (!location) { return location.code; }
        const KiottyNetHttpContentType type = KIOTTY_NET_HTTP_CONTENT_TYPE_BY_EXTENSION;
        const StaticSource source{ location.value, NO_MEMORY, type, StaticKind::DIRECTORY };
        return addStatic(parsed.value, source);
    }

    KiottyNetCode HttpRegistry::addFile(const char* url_path, const char* file_path)
    {
        const RoutePathResult parsed = parseRoutePath(url_path);
        if (!parsed) { return parsed.code; }
        const TextLocation location = parseLocation(file_path);
        if (!location) { return location.code; }
        const KiottyNetHttpContentType type = contentTypeOfPath(location.value);
        const StaticSource source{ location.value, NO_MEMORY, type, StaticKind::FILE };
        return addStatic(parsed.value, source);
    }

    KiottyNetCode HttpRegistry::addMemory(const char* url_path,
                                          KiottyNetHttpContentType type,
                                          KiottyNetSpan data)
    {
        const RoutePathResult parsed = parseRoutePath(url_path);
        if (!parsed) { return parsed.code; }
        const KiottyNetCode checked = checkMemory(type, data);
        if (checked != KIOTTY_NET_CODE_SUCCESS) { return checked; }
        const Span<const char> no_location{ nullptr, 0 };
        const StaticSource source{ no_location, data, type, StaticKind::MEMORY };
        return addStatic(parsed.value, source);
    }

    RouteMatch HttpRegistry::find(KiottyNetHttpMethod method, Span<const char> path) const
    {
        if (isWholeServer(path)) { return matchOf(MatchKind::OPTIONS, allMethods()); }
        const bool is_head = method == KIOTTY_NET_HTTP_METHOD_HEAD;
        const uint32_t bit = KIOTTY_NET_HTTP_METHOD_BIT(method);
        const uint32_t wanted = is_head ? bit | GET_BIT : bit;
        const RouteMatch found = findMethod(wanted, path);
        const bool is_missing = found.kind == MatchKind::NOT_ALLOWED;
        if (!is_missing) { return found; }
        return missing(method, found.allowed);
    }

    int32_t HttpRegistry::find(Span<const char> upgrade_path) const
    {
        for (const RouteEntry& entry : _entries)
        {
            if (entry.upgrade == NO_UPGRADE_ROUTE) { continue; }
            const Span<const char> text = entry.path.span();
            if (text.length != upgrade_path.length) { continue; }
            const bool is_same = std::memcmp(text.data, upgrade_path.data, text.length) == 0;
            if (is_same) { return entry.upgrade; }
        }
        return NO_UPGRADE_ROUTE;
    }

    KiottyNetCode HttpRegistry::addStatic(const RoutePath& path, const StaticSource& source)
    {
        const KiottyNetCode admitted = admit(path, STATIC_METHODS);
        if (admitted != KIOTTY_NET_CODE_SUCCESS) { return admitted; }
        RouteEntry entry{};
        (void)entry.path.assign(path.text);
        (void)entry.location.assign(source.location);
        const bool needs_separator = source.kind == StaticKind::DIRECTORY
                                     && !isSeparator(source.location[source.location.length - 1]);
        if (needs_separator) { (void)entry.location.append(Span<const char>{ "/", 1 }); }
        entry.memory = source.memory;
        entry.type = source.type;
        entry.methods = STATIC_METHODS;
        entry.upgrade = NO_UPGRADE_ROUTE;
        entry.kind = path.kind;
        entry.source = source.kind;
        _entries.push_back(entry);
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode HttpRegistry::admit(const RoutePath& path, uint32_t methods) const
    {
        if (hasEntry(path, methods)) { return KIOTTY_NET_CODE_DUPLICATE_RULE; }
        if (_entries.size() >= _max_routes) { return KIOTTY_NET_CODE_TABLE_FULL; }
        return KIOTTY_NET_CODE_SUCCESS;
    }

    bool HttpRegistry::hasEntry(const RoutePath& path, uint32_t method) const
    {
        for (const RouteEntry& entry : _entries)
        {
            const RoutePath stored{ entry.path.span(), entry.kind };
            const uint32_t taken = takenMethodsOf(entry.methods, entry.upgrade);
            const bool is_same = isSamePath(stored, path) && (taken & method) != 0;
            if (is_same) { return true; }
        }
        return false;
    }

    RouteMatch HttpRegistry::findMethod(uint32_t method, Span<const char> path) const
    {
        uint32_t allowed = 0;
        for (const RouteEntry& entry : _entries)
        {
            const RoutePath stored{ entry.path.span(), entry.kind };
            if (!matchesPath(stored, path)) { continue; }
            allowed |= entry.methods;
            if ((entry.methods & method) == 0) { continue; }
            return entryMatch(entry, stored.text, allowed);
        }
        return matchOf(MatchKind::NOT_ALLOWED, allowed);
    }

    RouteMatch HttpRegistry::entryMatch(const RouteEntry& entry,
                                        Span<const char> prefix,
                                        uint32_t allowed) const
    {
        const StaticTarget target{
            prefix, entry.location.span(), entry.memory, entry.type, entry.source,
        };
        RouteMatch match{ entry.route, target, entry.upgrade, allowed, MatchKind::ROUTE };
        if (entry.source != StaticKind::NONE) { match.kind = MatchKind::STATIC; }
        if (entry.upgrade == NO_UPGRADE_ROUTE) { return match; }
        match.kind = MatchKind::UPGRADE;
        return match;
    }

    RouteMatch HttpRegistry::missing(KiottyNetHttpMethod method, uint32_t allowed) const
    {
        const bool has_path = allowed != 0;
        const bool has_not_found = _not_found.onRequest != nullptr;
        RouteMatch not_found = matchOf(MatchKind::ROUTE, 0);
        not_found.route = _not_found;
        if (!has_path && has_not_found) { return not_found; }
        if (!has_path) { return matchOf(MatchKind::NOT_FOUND, 0); }
        const bool is_options = method == KIOTTY_NET_HTTP_METHOD_OPTIONS;
        if (is_options) { return matchOf(MatchKind::OPTIONS, allowed); }
        return matchOf(MatchKind::NOT_ALLOWED, allowed);
    }

    uint32_t HttpRegistry::allMethods() const
    {
        uint32_t methods = 0;
        for (const RouteEntry& entry : _entries)
        {
            methods |= entry.methods;
        }
        return methods;
    }

    namespace
    {
        bool isMethodKnown(KiottyNetHttpMethod method)
        {
            return method >= KIOTTY_NET_HTTP_METHOD_GET && method < KIOTTY_NET_HTTP_METHOD_COUNT;
        }

        bool isWholeServer(Span<const char> path)
        {
            return path.length == 1 && path[0] == '*';
        }

        bool isSamePath(const RoutePath& left, const RoutePath& right)
        {
            if (left.kind != right.kind) { return false; }
            if (left.text.length != right.text.length) { return false; }
            return std::memcmp(left.text.data, right.text.data, left.text.length) == 0;
        }

        bool isSeparator(char character)
        {
            return character == '/' || character == '\\';
        }

        TextLocation parseLocation(const char* text)
        {
            const TextResult parsed = parseText(text, MAX_LOCATION_LENGTH);
            if (!parsed) { return TextLocation::failure(parsed.code); }
            const KiottyNetCode invalid = KIOTTY_NET_CODE_INVALID_ARGUMENT;
            if (parsed.value.empty()) { return TextLocation::failure(invalid); }
            return TextLocation::success(parsed.value);
        }

        KiottyNetCode checkMemory(KiottyNetHttpContentType type, KiottyNetSpan data)
        {
            const bool is_listed = type >= KIOTTY_NET_HTTP_CONTENT_TYPE_OCTET_STREAM
                                   && type < KIOTTY_NET_HTTP_CONTENT_TYPE_BY_EXTENSION
                                   && type != KIOTTY_NET_HTTP_CONTENT_TYPE_EVENT_STREAM;
            const bool is_missing = data.data == nullptr && data.length > 0;
            if (!is_listed || is_missing) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
            const Span<const char> bytes{ data.data, data.length };
            const bool is_text = textKindOf(type) != TextKind::BINARY;
            if (is_text && !isUtf8(bytes)) { return KIOTTY_NET_CODE_INVALID_ENCODING; }
            return KIOTTY_NET_CODE_SUCCESS;
        }

        RouteMatch matchOf(MatchKind kind, uint32_t allowed)
        {
            const StaticTarget none{
                Span<const char>{ nullptr, 0 },
                Span<const char>{ nullptr, 0 },
                NO_MEMORY,
                KIOTTY_NET_HTTP_CONTENT_TYPE_OCTET_STREAM,
                StaticKind::NONE,
            };
            return RouteMatch{ KiottyNetHttpRoute{}, none, NO_UPGRADE_ROUTE, allowed, kind };
        }

        uint32_t takenMethodsOf(uint32_t methods, int32_t upgrade)
        {
            return upgrade == NO_UPGRADE_ROUTE ? methods : ALL_METHODS;
        }
    }
}

#include <cstdint>

namespace kiotty::net::implementation
{
    namespace
    {
        KiottyNetHttpContentType resolvedTypeOf(KiottyNetHttpContentType type,
                                                Span<const char> path);
    }

    KiottyNetCode attachFile(HttpSession& session,
                             KiottyNetHttpContentType type,
                             Span<const char> path)
    {
        const KiottyNetCode opened = session.file.open(path);
        if (opened != KIOTTY_NET_CODE_SUCCESS) { return KIOTTY_NET_CODE_NOT_FOUND; }
        const uint64_t size = session.file.size();
        const bool is_too_large = static_cast<uint64_t>(static_cast<size_t>(size)) != size;
        if (is_too_large) { session.file.close(); }
        if (is_too_large) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const KiottyNetSpan length{ nullptr, static_cast<size_t>(size) };
        const KiottyNetHttpContentType resolved = resolvedTypeOf(type, path);
        const KiottyNetCode set = session.response.setBody(resolved, length, BodyStorage::FILE);
        if (set != KIOTTY_NET_CODE_SUCCESS) { session.file.close(); }
        return set;
    }

    PieceResult pieceAt(HttpSession& session, size_t offset)
    {
        const size_t capacity = session.host.send_capacity;
        const ResponseFrame frame = session.response.frame();
        const FilePiece piece = frame.filePieceAt(offset, capacity);
        if (!piece.is_file) { return PieceResult::success(frame.chunkAt(offset, capacity)); }
        const FileReadResult read = session.file.read(piece.file_offset, piece.target);
        const bool is_whole = read && read.value == piece.target.length;
        if (!is_whole) { return PieceResult::failure(KIOTTY_NET_CODE_NOT_FOUND); }
        return PieceResult::success(Span<const char>{ piece.target.data, piece.target.length });
    }

    void detachFile(HttpSession& session)
    {
        session.file.close();
    }

    namespace
    {
        KiottyNetHttpContentType resolvedTypeOf(KiottyNetHttpContentType type,
                                                Span<const char> path)
        {
            const bool is_by_extension = type == KIOTTY_NET_HTTP_CONTENT_TYPE_BY_EXTENSION;
            return is_by_extension ? contentTypeOfPath(path) : type;
        }
    }
}

