#include <algorithm>

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr size_t   DEFAULT_MAX_CLIENTS = 1024;
        constexpr size_t   DEFAULT_CAPACITY_BYTES = 4096;
        constexpr size_t   DEFAULT_RECEIVE_CAPACITY_BYTES = 8192;
        constexpr uint32_t DEFAULT_CONNECT_TIMEOUT_MILLISECONDS = 5000;
        constexpr uint32_t DEFAULT_MAX_TRIAL = 1;
        constexpr uint32_t DEFAULT_TRIAL_INTERVAL_MILLISECONDS = 1000;
        constexpr uint32_t DEFAULT_SEND_TIMEOUT_MILLISECONDS = 30000;

        struct Capacities
        {
            size_t receive;
            size_t send;
            size_t push;
        };

        static_assert(sizeof(Capacities) == 3 * sizeof(size_t), "Capacities: unexpected padding");

        using MadeAddressResult = Result<KiottyNetAddress, KiottyNetCode>;

        MadeAddressResult            addressOf(KiottyNetTransport transport,
                                               Span<const char> name,
                                               uint16_t port);
        KiottyNetServerConfiguration defaultServer();
        KiottyNetClientConfiguration defaultClient();
        bool                         isTransportKnown(KiottyNetTransport transport);
        Capacities                  defaultCapacities();
        bool                         areCapacitiesValid(Capacities capacities);
        bool                         isWithin(size_t value, size_t maximum);
        bool                         isNoDelayKnown(KiottyNetNoDelay no_delay);
    }

    KiottyNetCode initializeTcpAddress(KiottyNetAddress& address,
                                       Span<const char> host,
                                       uint16_t port)
    {
        if (port == 0) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const MadeAddressResult made = addressOf(KIOTTY_NET_TRANSPORT_TCP, host, port);
        if (!made) { return made.code; }
        address = made.value;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode initializePipeAddress(KiottyNetAddress& address, Span<const char> pipe_name)
    {
        const MadeAddressResult made = addressOf(KIOTTY_NET_TRANSPORT_PIPE, pipe_name, 0);
        if (!made) { return made.code; }
        address = made.value;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    bool isAddressValid(const KiottyNetAddress& address)
    {
        if (!isTransportKnown(address.transport)) { return false; }
        const bool is_tcp = address.transport == KIOTTY_NET_TRANSPORT_TCP;
        if (is_tcp && address.port == 0) { return false; }
        const Span<const char> host = textOf(address.host);
        const bool is_terminated = host.length < sizeof(address.host);
        return is_terminated && !host.empty();
    }

    KiottyNetCode initializeServerConfiguration(KiottyNetServerConfiguration& configuration)
    {
        configuration = defaultServer();
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureServerMaxClients(KiottyNetServerConfiguration& configuration,
                                            size_t max_clients)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const bool is_valid = isWithin(max_clients, CONNECTIONS_PER_SERVER_LIMIT);
        if (!is_valid) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.max_clients = max_clients;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureServerBufferCapacity(KiottyNetServerConfiguration& configuration,
                                                size_t receive_capacity,
                                                size_t send_capacity,
                                                size_t push_capacity)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const Capacities capacities{ receive_capacity, send_capacity, push_capacity };
        if (!areCapacitiesValid(capacities)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.receive_capacity = capacities.receive;
        configuration.send_capacity = capacities.send;
        configuration.push_capacity = capacities.push;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureServerNoDelay(KiottyNetServerConfiguration& configuration,
                                         KiottyNetNoDelay no_delay)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isNoDelayKnown(no_delay)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.no_delay = no_delay;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureServerSendTimeout(KiottyNetServerConfiguration& configuration,
                                             uint32_t timeout_milliseconds)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.send_timeout_milliseconds = timeout_milliseconds;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode initializeClientConfiguration(KiottyNetClientConfiguration& configuration)
    {
        configuration = defaultClient();
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureClientBufferCapacity(KiottyNetClientConfiguration& configuration,
                                                size_t receive_capacity,
                                                size_t send_capacity,
                                                size_t push_capacity)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const Capacities capacities{ receive_capacity, send_capacity, push_capacity };
        if (!areCapacitiesValid(capacities)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.receive_capacity = capacities.receive;
        configuration.send_capacity = capacities.send;
        configuration.push_capacity = capacities.push;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureClientConnectTimeout(KiottyNetClientConfiguration& configuration,
                                                uint32_t timeout_milliseconds)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.connect_timeout_milliseconds = timeout_milliseconds;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureClientRetry(KiottyNetClientConfiguration& configuration,
                                       uint32_t max_trial,
                                       uint32_t trial_interval_milliseconds)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (max_trial == 0) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.max_trial = max_trial;
        configuration.trial_interval_milliseconds = trial_interval_milliseconds;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureClientNoDelay(KiottyNetClientConfiguration& configuration,
                                         KiottyNetNoDelay no_delay)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isNoDelayKnown(no_delay)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.no_delay = no_delay;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureClientSendTimeout(KiottyNetClientConfiguration& configuration,
                                             uint32_t timeout_milliseconds)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.send_timeout_milliseconds = timeout_milliseconds;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    bool isInitialized(const KiottyNetServerConfiguration& configuration)
    {
        return configuration.initialization_mark == INITIALIZATION_MARK;
    }

    bool isInitialized(const KiottyNetClientConfiguration& configuration)
    {
        return configuration.initialization_mark == INITIALIZATION_MARK;
    }

    Span<const char> hostnameOf(const KiottyNetAddress& address)
    {
        const bool is_tcp = address.transport == KIOTTY_NET_TRANSPORT_TCP;
        if (!is_tcp) { return Span<const char>{ address.host, 0 }; }
        return textOf(address.host);
    }

    bool writeText(Span<char> field, Span<const char> text)
    {
        field.fill('\0');
        if (field.empty()) { return false; }
        const Span<char> room{ field.data, field.length - 1 };
        return room.copyFrom(text);
    }

    NoDelay noDelayOf(KiottyNetNoDelay no_delay)
    {
        if (no_delay == KIOTTY_NET_NO_DELAY_ON) { return NoDelay::ENABLED; }
        return NoDelay::DISABLED;
    }

    namespace
    {
        bool isNoDelayKnown(KiottyNetNoDelay no_delay)
        {
            switch (no_delay)
            {
            case KIOTTY_NET_NO_DELAY_OFF:
            case KIOTTY_NET_NO_DELAY_ON:
                return true;
            }
            return false;
        }

        MadeAddressResult addressOf(KiottyNetTransport transport,
                                    Span<const char> name,
                                    uint16_t port)
        {
            if (name.empty()) { return MadeAddressResult::failure(INVALID); }
            KiottyNetAddress address{};
            address.transport = transport;
            const Span<char> field{ address.host, sizeof(address.host) };
            const bool written = writeText(field, name);
            if (!written) { return MadeAddressResult::failure(INVALID); }
            address.port = port;
            return MadeAddressResult::success(address);
        }

        bool isTransportKnown(KiottyNetTransport transport)
        {
            switch (transport)
            {
            case KIOTTY_NET_TRANSPORT_TCP:
            case KIOTTY_NET_TRANSPORT_PIPE:
                return true;
            }
            return false;
        }

        KiottyNetServerConfiguration defaultServer()
        {
            const Capacities capacities = defaultCapacities();
            KiottyNetServerConfiguration configuration{};
            configuration.initialization_mark = INITIALIZATION_MARK;
            configuration.max_clients = DEFAULT_MAX_CLIENTS;
            configuration.receive_capacity = capacities.receive;
            configuration.send_capacity = capacities.send;
            configuration.push_capacity = capacities.push;
            configuration.no_delay = KIOTTY_NET_NO_DELAY_ON;
            configuration.send_timeout_milliseconds = DEFAULT_SEND_TIMEOUT_MILLISECONDS;
            return configuration;
        }

        KiottyNetClientConfiguration defaultClient()
        {
            const Capacities capacities = defaultCapacities();
            KiottyNetClientConfiguration configuration{};
            configuration.initialization_mark = INITIALIZATION_MARK;
            configuration.receive_capacity = capacities.receive;
            configuration.send_capacity = capacities.send;
            configuration.push_capacity = capacities.push;
            configuration.connect_timeout_milliseconds = DEFAULT_CONNECT_TIMEOUT_MILLISECONDS;
            configuration.max_trial = DEFAULT_MAX_TRIAL;
            configuration.trial_interval_milliseconds = DEFAULT_TRIAL_INTERVAL_MILLISECONDS;
            configuration.no_delay = KIOTTY_NET_NO_DELAY_ON;
            configuration.send_timeout_milliseconds = DEFAULT_SEND_TIMEOUT_MILLISECONDS;
            return configuration;
        }

        Capacities defaultCapacities()
        {
            const size_t receive = DEFAULT_RECEIVE_CAPACITY_BYTES;
            return Capacities{ std::min(receive, MemoryLimits::RECEIVE_CAPACITY),
                               std::min(DEFAULT_CAPACITY_BYTES, MemoryLimits::SEND_CAPACITY),
                               std::min(DEFAULT_CAPACITY_BYTES, MemoryLimits::PUSH_CAPACITY) };
        }

        bool areCapacitiesValid(Capacities capacities)
        {
            const bool receive = isWithin(capacities.receive, MemoryLimits::RECEIVE_CAPACITY);
            const bool send = isWithin(capacities.send, MemoryLimits::SEND_CAPACITY);
            const bool push = isWithin(capacities.push, MemoryLimits::PUSH_CAPACITY);
            return receive && send && push;
        }

        bool isWithin(size_t value, size_t maximum)
        {
            return value >= 1 && value <= maximum;
        }
    }
}

#include <cstddef>

namespace kiotty::net::implementation
{
    namespace
    {
        constexpr uint32_t VERSION_V12_BIT = static_cast<uint32_t>(KIOTTY_NET_TLS_VERSION_V12);
        constexpr uint32_t VERSION_V13_BIT = static_cast<uint32_t>(KIOTTY_NET_TLS_VERSION_V13);
        constexpr uint32_t ALL_VERSIONS = VERSION_V12_BIT | VERSION_V13_BIT;
        constexpr uint32_t ALL_V12_SUITES =
            static_cast<uint32_t>(KIOTTY_NET_TLS_V12_CIPHER_SUITE_ECDHE_ECDSA_AES256_GCM_SHA384)
            | static_cast<uint32_t>(KIOTTY_NET_TLS_V12_CIPHER_SUITE_ECDHE_RSA_AES256_GCM_SHA384)
            | static_cast<uint32_t>(KIOTTY_NET_TLS_V12_CIPHER_SUITE_ECDHE_ECDSA_CHACHA20_POLY1305)
            | static_cast<uint32_t>(KIOTTY_NET_TLS_V12_CIPHER_SUITE_ECDHE_RSA_CHACHA20_POLY1305);
        constexpr uint32_t ALL_V13_SUITES =
            static_cast<uint32_t>(KIOTTY_NET_TLS_V13_CIPHER_SUITE_AES_128_GCM_SHA256)
            | static_cast<uint32_t>(KIOTTY_NET_TLS_V13_CIPHER_SUITE_AES_256_GCM_SHA384)
            | static_cast<uint32_t>(KIOTTY_NET_TLS_V13_CIPHER_SUITE_CHACHA20_POLY1305_SHA256)
            | static_cast<uint32_t>(KIOTTY_NET_TLS_V13_CIPHER_SUITE_AES_128_CCM_SHA256)
            | static_cast<uint32_t>(KIOTTY_NET_TLS_V13_CIPHER_SUITE_AES_128_CCM8_SHA256);

        bool isIdentityValid(const TlsIdentityText& text);
        void writeIdentity(KiottyNetTlsIdentity& identity, const TlsIdentityText& text);
        bool isTrustAccepted(KiottyNetClientAuthentication mode, Span<const char> path);
        bool writePath(char (&field)[KIOTTY_NET_MAX_PATH_LENGTH], Span<const char> path);
        bool isSuiteSetValid(uint32_t suites, uint32_t known);
        bool isVerificationKnown(KiottyNetTlsVerification verification);
    }

    KiottyNetCode initializeTlsServerConfiguration(KiottyNetTlsServerConfiguration& configuration,
                                                   const TlsIdentityText& identity)
    {
        if (!isIdentityValid(identity)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration = KiottyNetTlsServerConfiguration{};
        configuration.initialization_mark = INITIALIZATION_MARK;
        configuration.versions = ALL_VERSIONS;
        configuration.v12_cipher_suites = ALL_V12_SUITES;
        configuration.v13_cipher_suites = ALL_V13_SUITES;
        configuration.client_authentication = KIOTTY_NET_CLIENT_AUTHENTICATION_NONE;
        writeIdentity(configuration.identity, identity);
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsServerVersions(KiottyNetTlsServerConfiguration& configuration,
                                             uint32_t versions)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isSuiteSetValid(versions, ALL_VERSIONS)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.versions = versions;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsServerV12CipherSuites(KiottyNetTlsServerConfiguration& configuration,
                                                    uint32_t suites)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isSuiteSetValid(suites, ALL_V12_SUITES)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.v12_cipher_suites = suites;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsServerV13CipherSuites(KiottyNetTlsServerConfiguration& configuration,
                                                    uint32_t suites)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isSuiteSetValid(suites, ALL_V13_SUITES)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.v13_cipher_suites = suites;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsServerClientAuthentication(
        KiottyNetTlsServerConfiguration& configuration,
        KiottyNetClientAuthentication mode,
        Span<const char> trust_store_path)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const bool is_accepted = isTrustAccepted(mode, trust_store_path);
        if (!is_accepted) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const bool written = writePath(configuration.trust_store_path, trust_store_path);
        if (!written) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.client_authentication = mode;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode initializeTlsClientConfiguration(KiottyNetTlsClientConfiguration& configuration)
    {
        configuration = KiottyNetTlsClientConfiguration{};
        configuration.initialization_mark = INITIALIZATION_MARK;
        configuration.versions = ALL_VERSIONS;
        configuration.v12_cipher_suites = ALL_V12_SUITES;
        configuration.v13_cipher_suites = ALL_V13_SUITES;
        configuration.verification = KIOTTY_NET_TLS_VERIFICATION_SERVER_AND_HOSTNAME;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsClientVersions(KiottyNetTlsClientConfiguration& configuration,
                                             uint32_t versions)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isSuiteSetValid(versions, ALL_VERSIONS)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.versions = versions;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsClientV12CipherSuites(KiottyNetTlsClientConfiguration& configuration,
                                                    uint32_t suites)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isSuiteSetValid(suites, ALL_V12_SUITES)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.v12_cipher_suites = suites;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsClientV13CipherSuites(KiottyNetTlsClientConfiguration& configuration,
                                                    uint32_t suites)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isSuiteSetValid(suites, ALL_V13_SUITES)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.v13_cipher_suites = suites;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsClientTrustStore(KiottyNetTlsClientConfiguration& configuration,
                                               Span<const char> trust_store_path)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (trust_store_path.empty()) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const bool written = writePath(configuration.trust_store_path, trust_store_path);
        if (!written) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsClientVerification(KiottyNetTlsClientConfiguration& configuration,
                                                 KiottyNetTlsVerification verification)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isVerificationKnown(verification)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        configuration.verification = verification;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode configureTlsClientIdentity(KiottyNetTlsClientConfiguration& configuration,
                                             const TlsIdentityText& identity)
    {
        if (!isInitialized(configuration)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (!isIdentityValid(identity)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        writeIdentity(configuration.identity, identity);
        return KIOTTY_NET_CODE_SUCCESS;
    }

    bool isInitialized(const KiottyNetTlsServerConfiguration& configuration)
    {
        return configuration.initialization_mark == INITIALIZATION_MARK;
    }

    bool isInitialized(const KiottyNetTlsClientConfiguration& configuration)
    {
        return configuration.initialization_mark == INITIALIZATION_MARK;
    }

    namespace
    {
        bool isIdentityValid(const TlsIdentityText& text)
        {
            const size_t path_limit = KIOTTY_NET_MAX_PATH_LENGTH;
            const size_t password_limit = KIOTTY_NET_MAX_PASSWORD_LENGTH;
            const bool is_named = !text.certificate_file.empty() && !text.key_file.empty();
            const bool is_certificate_fitting = text.certificate_file.length < path_limit;
            const bool is_key_fitting = text.key_file.length < path_limit;
            const bool is_password_fitting = text.key_password.length < password_limit;
            return is_named && is_certificate_fitting && is_key_fitting && is_password_fitting;
        }

        void writeIdentity(KiottyNetTlsIdentity& identity, const TlsIdentityText& text)
        {
            const Span<char> password{ identity.key_password, sizeof(identity.key_password) };
            static_cast<void>(writePath(identity.certificate_file, text.certificate_file));
            static_cast<void>(writePath(identity.key_file, text.key_file));
            static_cast<void>(writeText(password, text.key_password));
        }

        bool isTrustAccepted(KiottyNetClientAuthentication mode, Span<const char> path)
        {
            switch (mode)
            {
            case KIOTTY_NET_CLIENT_AUTHENTICATION_NONE:
                return path.empty();
            case KIOTTY_NET_CLIENT_AUTHENTICATION_OPTIONAL:
            case KIOTTY_NET_CLIENT_AUTHENTICATION_REQUIRED:
                return !path.empty();
            }
            return false;
        }

        bool writePath(char (&field)[KIOTTY_NET_MAX_PATH_LENGTH], Span<const char> path)
        {
            return writeText(Span<char>{ field, KIOTTY_NET_MAX_PATH_LENGTH }, path);
        }

        bool isSuiteSetValid(uint32_t suites, uint32_t known)
        {
            const bool has_unknown = (suites & ~known) != 0;
            return suites != 0 && !has_unknown;
        }

        bool isVerificationKnown(KiottyNetTlsVerification verification)
        {
            switch (verification)
            {
            case KIOTTY_NET_TLS_VERIFICATION_NONE:
            case KIOTTY_NET_TLS_VERIFICATION_SERVER:
            case KIOTTY_NET_TLS_VERIFICATION_SERVER_AND_HOSTNAME:
                return true;
            }
            return false;
        }
    }
}

