namespace kiotty::net::implementation
{
    namespace
    {
        constexpr uint64_t WAIT_FOREVER = 0;
    }

    RunGate::RunGate()
        : _parker()
        , _is_running(false)
        , _runner()
        , _code(KIOTTY_NET_CODE_SUCCESS)
        , _phase(RunPhase::IDLE)
    {
    }

    bool RunGate::enter()
    {
        const bool was_running = _is_running.exchange(true);
        if (was_running) { return false; }
        _runner.store(std::this_thread::get_id());
        _parker.unpark([this]() { _phase = RunPhase::IDLE; });
        return true;
    }

    void RunGate::start()
    {
        _parker.unpark([this]() { _phase = RunPhase::RUNNING; });
    }

    void RunGate::finish(KiottyNetCode code)
    {
        _parker.unpark([this, code]() {
            _code = code;
            _phase = RunPhase::FINISHED;
            _is_running.store(false);
            _runner.store(std::thread::id());
        });
    }

    KiottyNetCode RunGate::await(uint64_t timeout_milliseconds)
    {
        KiottyNetCode answer = KIOTTY_NET_CODE_TIMEOUT;
        const auto settled = [this, &answer]() {
            if (_phase == RunPhase::IDLE) { return false; }
            answer = _phase == RunPhase::RUNNING ? KIOTTY_NET_CODE_SUCCESS : _code;
            return true;
        };
        (void)_parker.park(settled, timeout_milliseconds);
        return answer;
    }

    void RunGate::join()
    {
        (void)_parker.park([this]() { return !_is_running.load(); }, WAIT_FOREVER);
    }

    void RunGate::clear()
    {
        _parker.unpark([this]() {
            _code = KIOTTY_NET_CODE_SUCCESS;
            _phase = RunPhase::IDLE;
        });
    }

    std::thread::id RunGate::runner() const
    {
        return _runner.load();
    }
}

#include <thread>

namespace kiotty::net::implementation
{
    RunLifetime::RunLifetime(RunGate& gate, std::atomic<bool>& is_abandoned)
        : _gate(gate)
        , _is_abandoned(is_abandoned)
    {
    }

    bool RunLifetime::isRunner() const
    {
        return _gate.runner() == std::this_thread::get_id();
    }

    void RunLifetime::abandon()
    {
        _is_abandoned.store(true);
    }

    bool RunLifetime::isReleasable() const
    {
        return _is_abandoned.load() && _gate.runner() == std::thread::id();
    }

    void RunLifetime::join()
    {
        _gate.join();
    }
}

namespace kiotty::net::implementation
{
    ConnectionAccess::ConnectionAccess(NotificationDesk& desk,
                                       EventListener& listener,
                                       const IoLoop& loop)
        : _desk(desk)
        , _listener(listener)
        , _loop(loop)
    {
    }

    KiottyNetCode ConnectionAccess::notify(int64_t id, KiottyNetSpan data)
    {
        const KiottyNetCode staged = _desk.notify(PoolHandle::fromValue(id), data);
        if (staged != KIOTTY_NET_CODE_SUCCESS) { return staged; }
        (void)_listener.wake();
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode ConnectionAccess::notify(int64_t id, Span<const KiottyNetSpan> pieces)
    {
        const KiottyNetCode staged = _desk.notify(PoolHandle::fromValue(id), pieces);
        if (staged != KIOTTY_NET_CODE_SUCCESS) { return staged; }
        (void)_listener.wake();
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetResult ConnectionAccess::readStream(int64_t id,
                                                 Span<char> buffer,
                                                 uint32_t timeout_milliseconds)
    {
        const ConnectionResult found = working(id);
        if (!found) { return KiottyNetResult{ 0, found.code }; }
        return found.value().flows().work.stream().read(buffer, timeout_milliseconds);
    }

    KiottyNetResult ConnectionAccess::writeStream(int64_t id,
                                                  KiottyNetSpan data,
                                                  uint32_t timeout_milliseconds)
    {
        const ConnectionResult found = working(id);
        if (!found) { return KiottyNetResult{ 0, found.code }; }
        return found.value().flows().work.stream().write(data, timeout_milliseconds);
    }

    KiottyNetCode ConnectionAccess::writeStreamFile(int64_t id,
                                                    Span<const char> path,
                                                    FileRange range,
                                                    uint32_t timeout_milliseconds)
    {
        const ConnectionResult found = working(id);
        if (!found) { return found.code; }
        ConnectionStream stream = found.value().flows().work.stream();
        return stream.writeFile(path, range.offset, range.length, timeout_milliseconds);
    }

    bool ConnectionAccess::isStreamOpen(int64_t id)
    {
        const ConnectionResult found = working(id);
        if (!found) { return false; }
        return found.value().flows().work.stream().connected();
    }

    KiottyNetCode ConnectionAccess::closeStream(int64_t id, const KiottyNetConnectionAction& then)
    {
        const KiottyNetCode closed = _desk.closeStream(PoolHandle::fromValue(id), then);
        (void)_listener.wake();
        return closed;
    }

    ConnectionResult ConnectionAccess::working(int64_t id)
    {
        if (_loop.isIoThread()) { return ConnectionResult::failure(KIOTTY_NET_CODE_BUSY); }
        return _desk.working(PoolHandle::fromValue(id));
    }
}

namespace kiotty::net::implementation
{
    namespace
    {
        ConnectionLimits limitsOf(const KiottyNetServerConfiguration& configuration);
        size_t           listenerCapacityOf(size_t max_clients);
    }

    Server::Server()
        : _connections()
        , _host(_connections)
        , _desk(_connections, _host.notificationMutex())
        , _listener()
        , _acceptor()
        , _profile()
        , _loop()
        , _gate()
        , _is_abandoned(false)
        , _configuration()
    {
    }

    Server::~Server() = default;

    KiottyNetCode Server::initialize(PoolHandle id, const KiottyNetServerConfiguration& server)
    {
        (void)id;
        if (!isInitialized(server)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const bool is_sized = _connections.resize(server.max_clients);
        if (!is_sized) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const SocketCode opened = _listener.open(listenerCapacityOf(server.max_clients));
        if (opened != SocketCode::SUCCESS) { return toNetCode(opened); }
        const ConnectionLimits limits = limitsOf(server);
        _host.initialize(limits, server.max_clients, cipherOf(limits));
        _configuration = server;
        _gate.clear();
        return KIOTTY_NET_CODE_SUCCESS;
    }

    void Server::reset() noexcept
    {
        close();
        _gate.join();
        _loop.reset();
        _listener.close();
        _profile.close();
        _gate.clear();
        _is_abandoned.store(false);
    }

    KiottyNetCode Server::run(const Handler& handler,
                              const KiottyNetAddress& address,
                              const KiottyNetTlsServerConfiguration* tls)
    {
        const KiottyNetCode checked = handler.validate();
        if (checked != KIOTTY_NET_CODE_SUCCESS) { return checked; }
        if (!isAddressValid(address)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        if (tls != nullptr && !isInitialized(*tls)) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const bool entered = _gate.enter();
        if (!entered) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        _loop.reset();
        const KiottyNetCode secured = openProfile(tls);
        if (secured != KIOTTY_NET_CODE_SUCCESS) { return leave(secured); }
        const LoopParts parts{ _host, _listener, _acceptor, _profile, handler };
        const KiottyNetCode opened = listen(address);
        if (opened != KIOTTY_NET_CODE_SUCCESS) { return leave(opened); }
        _gate.start();
        (void)_loop.run(parts, StopPolicy::WHEN_STOPPED);
        return leave(KIOTTY_NET_CODE_CLOSED);
    }

    void Server::close()
    {
        _loop.stop();
        (void)_listener.wake();
    }

    KiottyNetCode Server::await(uint64_t timeout_milliseconds)
    {
        return _gate.await(timeout_milliseconds);
    }

    KiottyNetCode Server::broadcast(KiottyNetSpan data)
    {
        const KiottyNetCode staged = _desk.broadcast(data);
        if (staged != KIOTTY_NET_CODE_SUCCESS) { return staged; }
        (void)_listener.wake();
        return KIOTTY_NET_CODE_SUCCESS;
    }

    RunLifetime Server::lifetime()
    {
        return RunLifetime(_gate, _is_abandoned);
    }

    KiottyNetCode Server::notify(int64_t id, KiottyNetSpan data)
    {
        return access().notify(id, data);
    }

    KiottyNetCode Server::notify(int64_t id, Span<const KiottyNetSpan> pieces)
    {
        return access().notify(id, pieces);
    }

    KiottyNetConnectionInfo Server::info(int64_t id) const
    {
        return _desk.info(PoolHandle::fromValue(id));
    }

    KiottyNetResult Server::readStream(int64_t id,
                                       Span<char> buffer,
                                       uint32_t timeout_milliseconds)
    {
        return access().readStream(id, buffer, timeout_milliseconds);
    }

    KiottyNetResult Server::writeStream(int64_t id,
                                        KiottyNetSpan data,
                                        uint32_t timeout_milliseconds)
    {
        return access().writeStream(id, data, timeout_milliseconds);
    }

    KiottyNetCode Server::writeStreamFile(int64_t id,
                                          Span<const char> path,
                                          FileRange range,
                                          uint32_t timeout_milliseconds)
    {
        return access().writeStreamFile(id, path, range, timeout_milliseconds);
    }

    bool Server::isStreamOpen(int64_t id)
    {
        return access().isStreamOpen(id);
    }

    KiottyNetCode Server::closeStream(int64_t id, const KiottyNetConnectionAction& then)
    {
        return access().closeStream(id, then);
    }

    KiottyNetCode Server::openProfile(const KiottyNetTlsServerConfiguration* tls)
    {
        _profile.close();
        if (tls == nullptr) { return KIOTTY_NET_CODE_SUCCESS; }
        return _profile.openServer(*tls);
    }

    KiottyNetCode Server::listen(const KiottyNetAddress& address)
    {
        const NoDelay no_delay = noDelayOf(_configuration.no_delay);
        const SocketCode opened = _acceptor.open(address, LISTEN_BACKLOG, no_delay);
        if (opened != SocketCode::SUCCESS) { return toNetCode(opened); }
        const SocketCode attached = _acceptor.attach(_listener);
        if (attached == SocketCode::SUCCESS) { return KIOTTY_NET_CODE_SUCCESS; }
        _acceptor.close();
        return toNetCode(attached);
    }

    KiottyNetCode Server::leave(KiottyNetCode code)
    {
        _gate.finish(code);
        return code;
    }

    ConnectionAccess Server::access()
    {
        return ConnectionAccess(_desk, _listener, _loop);
    }

    namespace
    {
        ConnectionLimits limitsOf(const KiottyNetServerConfiguration& configuration)
        {
            return ConnectionLimits{ configuration.receive_capacity,
                                     configuration.send_capacity,
                                     configuration.push_capacity,
                                     configuration.send_timeout_milliseconds };
        }

        size_t listenerCapacityOf(size_t max_clients)
        {
            return 2 * max_clients + 2;
        }
    }
}

