namespace kiotty::net::implementation
{
    namespace
    {
        constexpr size_t MAX_CLIENT_PROTOCOL_TEXT = KIOTTY_NET_MAX_WEB_SOCKET_PROTOCOL_LENGTH - 1;

        bool isUpgradeTarget(Span<const char> path)
        {
            if (path.empty() || path[0] != '/') { return false; }
            for (const char character : path)
            {
                if (!isVisibleCharacter(character)) { return false; }
            }
            return true;
        }

        bool isProtocolNameList(Span<const char> list)
        {
            size_t start = 0;
            while (start <= list.length)
            {
                const size_t comma = findCharacter(list, ',', start);
                const Span<const char> item{ list.data + start, comma - start };
                if (!isToken(trimWhitespace(item))) { return false; }
                start = comma + 1;
            }
            return true;
        }

        RegistrationResult clientHostOf(WebSocketClient& client, bool has_action)
        {
            if (!has_action) { return RegistrationResult::failure(INVALID); }
            return client.registration();
        }
    }

    KiottyNetCode setWebSocketClientProtocols(WebSocketClient& client, const char* protocols)
    {
        if (protocols == nullptr) { return client.setProtocols(Span<const char>{ nullptr, 0 }); }
        const TextResult text = parseText(protocols, MAX_CLIENT_PROTOCOL_TEXT);
        if (!text) { return INVALID; }
        const bool is_list = text.value.empty() || isProtocolNameList(text.value);
        if (!is_list) { return INVALID; }
        return client.setProtocols(text.value);
    }

    KiottyNetCode onWebSocketClientOpen(WebSocketClient& client,
                                        KiottyNetWebSocketClientOpenAction on_open)
    {
        const RegistrationResult host = clientHostOf(client, on_open != nullptr);
        if (!host) { return host.code; }
        handlerOf(host.value()).client.events.on_open = on_open;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode onWebSocketClientMessage(WebSocketClient& client,
                                           KiottyNetWebSocketClientMessageAction on_message)
    {
        const RegistrationResult host = clientHostOf(client, on_message != nullptr);
        if (!host) { return host.code; }
        handlerOf(host.value()).client.events.on_message = on_message;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode onWebSocketClientClose(WebSocketClient& client,
                                         KiottyNetWebSocketClientCloseAction on_close)
    {
        const RegistrationResult host = clientHostOf(client, on_close != nullptr);
        if (!host) { return host.code; }
        handlerOf(host.value()).client.events.on_close = on_close;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode onWebSocketClientError(WebSocketClient& client,
                                         KiottyNetWebSocketClientErrorAction on_error)
    {
        const RegistrationResult host = clientHostOf(client, on_error != nullptr);
        if (!host) { return host.code; }
        host.value().notices.setError(on_error);
        return KIOTTY_NET_CODE_SUCCESS;
    }

    KiottyNetCode runWebSocketClient(WebSocketClient& client, const ClientRun& run)
    {
        if (!isUpgradeTarget(run.path)) { return INVALID; }
        return client.run(run);
    }

    KiottyNetCode byeWebSocketClient(WebSocketClient& client, uint16_t status, const char* reason)
    {
        return closeWebSocket(client.socket(), status, reason);
    }

    KiottyNetCode sendWebSocketClient(WebSocketClient& client,
                                      KiottyNetWebSocketOpcode opcode,
                                      KiottyNetSpan data)
    {
        return sendWebSocket(client.socket(), opcode, data);
    }
}

#ifndef KIOTTY_NET_INTERNAL_BASE_DATA_INFRA_SOCKET_SOCKET_STARTUP_H
#define KIOTTY_NET_INTERNAL_BASE_DATA_INFRA_SOCKET_SOCKET_STARTUP_H

namespace kiotty::net::implementation
{
    SocketCode startSockets();
    void       stopSockets();
}

#endif

#include <cassert>

namespace kiotty::net::implementation
{
    namespace
    {
        template <class T>
        void sweep(LazyReusablePool<T>& pool)
        {
            pool.forEachActive([&pool](T& owner) {
                if (owner.lifetime().isReleasable()) { pool.release(owner); }
            });
        }

        template <class T>
        void closeAll(LazyReusablePool<T>& pool)
        {
            pool.forEachActive([](T& owner) { owner.close(); });
        }

        template <class T>
        void joinAll(LazyReusablePool<T>& pool)
        {
            pool.forEachActive([](T& owner) {
                RunLifetime life = owner.lifetime();
                assert(!life.isRunner());
                if (!life.isRunner()) { life.join(); }
            });
        }
    }

    ContextResult Context::open()
    {
        static KiottyNetContextImpl instance;
        Context& context = instance;
        const std::lock_guard<std::mutex> lock(context._mutex);
        const KiottyNetCode initialized = context.initialize();
        if (initialized != KIOTTY_NET_CODE_SUCCESS) { return ContextResult::failure(initialized); }
        return ContextResult::success(instance);
    }

    void Context::release()
    {
        {
            const std::lock_guard<std::mutex> lock(_mutex);
            if (_phase != ContextPhase::OPEN) { return; }
            _phase = ContextPhase::RELEASING;
        }
        closeAll(_servers);
        closeAll(_event_clients);
        closeAll(_http_servers);
        closeAll(_websocket_clients);
        joinAll(_servers);
        joinAll(_event_clients);
        joinAll(_http_servers);
        joinAll(_websocket_clients);
        finishRelease();
    }

    ServerResult Context::createServer(const KiottyNetServerConfiguration& configuration)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN)
        {
            return ServerResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT);
        }
        sweep(_servers);
        return _servers.acquire(configuration);
    }

    StreamClientResult Context::createStreamClient(
        const KiottyNetClientConfiguration& configuration)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN)
        {
            return StreamClientResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT);
        }
        return _stream_clients.acquire(configuration);
    }

    EventClientResult Context::createEventClient(const KiottyNetClientConfiguration& configuration)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN)
        {
            return EventClientResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT);
        }
        sweep(_event_clients);
        return _event_clients.acquire(configuration);
    }

    HttpServerResult Context::create(const HttpServerConfiguration& configuration)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN)
        {
            return HttpServerResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT);
        }
        sweep(_http_servers);
        return _http_servers.acquire(configuration);
    }

    WebSocketClientResult Context::create(
        const WebSocketClientConfiguration& configuration)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN)
        {
            return WebSocketClientResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT);
        }
        sweep(_websocket_clients);
        return _websocket_clients.acquire(configuration);
    }

    HttpClientResult Context::create(const HttpClientConfiguration& configuration)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN)
        {
            return HttpClientResult::failure(KIOTTY_NET_CODE_INVALID_ARGUMENT);
        }
        return _http_clients.acquire(configuration);
    }

    void Context::destroy(KiottyNetServer& server)
    {
        retire(_servers, server);
    }

    void Context::destroy(KiottyNetStreamClient& client)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN) { return; }
        _stream_clients.release(client);
    }

    void Context::destroy(KiottyNetEventClient& client)
    {
        retire(_event_clients, client);
    }

    void Context::destroy(KiottyNetHttpServer& server)
    {
        retire(_http_servers, server);
    }

    void Context::destroy(KiottyNetWebSocketClient& client)
    {
        retire(_websocket_clients, client);
    }

    void Context::destroy(KiottyNetHttpClient& client)
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN) { return; }
        _http_clients.release(client);
    }

    Context::Context()
        : _servers()
        , _stream_clients()
        , _event_clients()
        , _http_servers()
        , _websocket_clients()
        , _http_clients()
        , _mutex()
        , _phase(ContextPhase::CLOSED)
    {
    }

    Context::~Context() = default;

    template <class T>
    void Context::retire(LazyReusablePool<T>& pool, T& owner)
    {
        RunLifetime life = owner.lifetime();
        owner.close();
        if (life.isRunner())
        {
            life.abandon();
            return;
        }
        life.join();
        const std::lock_guard<std::mutex> lock(_mutex);
        if (_phase != ContextPhase::OPEN) { return; }
        pool.release(owner);
    }

    KiottyNetCode Context::initialize()
    {
        if (_phase == ContextPhase::OPEN) { return KIOTTY_NET_CODE_SUCCESS; }
        if (_phase == ContextPhase::RELEASING) { return KIOTTY_NET_CODE_INVALID_ARGUMENT; }
        const SocketCode started = startSockets();
        if (started != SocketCode::SUCCESS) { return toNetCode(started); }
        const KiottyNetCode secured = initializeTlsLibrary();
        if (secured != KIOTTY_NET_CODE_SUCCESS)
        {
            stopSockets();
            return secured;
        }
        _phase = ContextPhase::OPEN;
        return KIOTTY_NET_CODE_SUCCESS;
    }

    void Context::finishRelease()
    {
        const std::lock_guard<std::mutex> lock(_mutex);
        _servers.clear();
        _stream_clients.clear();
        _event_clients.clear();
        _http_servers.clear();
        _websocket_clients.clear();
        _http_clients.clear();
        stopSockets();
        _phase = ContextPhase::CLOSED;
    }
}


